"offset","type":"uint256"}],"name":"getHistoricalProofPeriodStartBlock","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"hub","outputs":[{"internalType":"contract Hub","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"identityStorage","outputs":[{"internalType":"contract IdentityStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"initialize","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"isPendingProofingPeriodDuration","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"knowledgeAssetStorage","outputs":[{"internalType":"contract DKGKnowledgeAssets","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"name","outputs":[{"internalType":"string","name":"","type":"string"}],"stateMutability":"pure","type":"function"},{"inputs":[],"name":"parametersStorage","outputs":[{"internalType":"contract ParametersStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"bytes32","name":"seed","type":"bytes32"}],"name":"previewChallengeForSeed","outputs":[{"internalType":"uint256","name":"cgId","type":"uint256"},{"internalType":"uint256","name":"kaId","type":"uint256"},{"internalType":"uint256","name":"chunkId","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"profileStorage","outputs":[{"internalType":"contract ProfileStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"cgId","type":"uint256"},{"internalType":"uint256","name":"startIndex","type":"uint256"},{"internalType":"uint256","name":"maxScan","type":"uint256"}],"name":"pruneExpiredKnowledgeAssets","outputs":[{"internalType":"uint256","name":"removed","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"randomSamplingStorage","outputs":[{"internalType":"contract RandomSamplingStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint16","name":"durationInBlocks","type":"uint16"}],"name":"setProofingPeriodDurationInBlocks","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"bool","name":"_status","type":"bool"}],"name":"setStatus","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"shardingTableStorage","outputs":[{"internalType":"contract ShardingTableStorage","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"status","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"bytes","name":"content","type":"bytes"},{"internalType":"bytes32[]","name":"merkleProof","type":"bytes32[]"}],"name":"submitProof","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"updateAndGetActiveProofPeriodStartBlock","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"version","outputs":[{"internalType":"string","name":"","type":"string"}],"stateMutability":"pure","type":"function"}],"devdoc":{"kind":"dev","methods":{"calculateNodeScore(uint72)":{"details":"Calculates the node score based on stake, publishing activity, and ask alignment Implements anti-sybil multiplicative score formula (RFC-26 update) Formula: nodeScore(t) = S(t) * (c + 0.86 * P(t) + 0.60 * A(t) * P(t)) Where: - S(t) = sqrt(nodeEffectiveStake / STAKE_CAP) - sublinear conviction stake scaling - P(t) = K_n / K_total - publishing share over 4 epochs (t-3, t-2, t-1, t) - A(t) = 1 - |nodeAsk - networkPrice| / networkPrice - ask alignment factor - c = 0.002 (STAKE_BASELINE_COEFFICIENT) - small baseline for staked non-publishers The multiplicative structure ensures stake amplifies contribution rather than providing an unconditional reward floor. The small c coefficient preserves a minimal incentive for staking even without publishing, preventing a hard cliff while making sybil extraction economically unattractive. All calculations use 18-decimal precision for accuracy","params":{"identityId":"The node identity to calculate score for"},"returns":{"_0":"score18 The calculated node score scaled by 18-decimal for precision"}},"constructor":{"details":"Constructor initializes the contract with essential parameters for random sampling Only called once during deployment","params":{"hubAddress":"Address of the Hub contract for access control"}},"createChallenge()":{"details":"Creates a new challenge for the calling node in the current proofing period Caller must have a registered profile and cannot have an active unsolved challenge Generates a random knowledge asset and chunk to be proven Can only create one challenge per proofing period"},"getActiveProofPeriodStatus()":{"details":"Returns the status of the current active proof period including start block and whether it's still active","returns":{"_0":"ProofPeriodStatus struct containing start block and active status"}},"getActiveProofingPeriodDurationInBlocks()":{"details":"Returns the currently active proofing period duration in blocks Automatically selects the appropriate duration based on current epoch","returns":{"_0":"Duration in blocks of the currently active proofing period"}},"getHistoricalProofPeriodStartBlock(uint256,uint256)":{"details":"Calculates the start block of a historical proof period based on current period and offset Used to determine proof periods from the past for validation purposes","params":{"offset":"Number of periods to go back (must be > 0)","proofPeriodStartBlock":"Start block of a valid proof period (must be > 0 and aligned to period boundaries)"},"returns":{"_0":"Start block of the historical proof period"}},"initialize()":{"details":"Initializes the contract by connecting to all required Hub dependencies Called once during deployment to set up contract references for storage and computation Only the Hub can call this function"},"isPendingProofingPeriodDuration()":{"details":"Checks if there is a pending proofing period duration that hasn't taken effect yet","returns":{"_0":"True if there is a pending duration change, false otherwise"}},"name()":{"details":"Returns the name of this contract Used for contract identification and versioning"},"previewChallengeForSeed(bytes32)":{"details":"Read-only public preview of {_pickWeightedChallenge}. Lets nodes      and indexers simulate a draw for an arbitrary seed without writing      to storage; tests use it to drive distribution regression with      deterministic per-draw seeds and no block-mining.      Because this view shares the underlying picker with the production      path, any change to the weighted-selection logic is reflected in      both call sites — no test-only drift.","params":{"seed":"The 32-byte seed to draw against. Production callers                   should pass a high-entropy hash; tests pass deterministic                   per-iteration seeds for distribution analysis."},"returns":{"cgId":"     Selected Context Graph id.","chunkId":"  Selected **V10 Merkle leaf index** within the KA (same field                   name as V8 byte-chunk index for struct compatibility).      Always previews the CURRENT epoch: the CG draw reads the live BIT snapshot      (`bitTotal`/`findStrictGtExcluding`), which the index cannot reconstruct for a past or      future epoch, so a `targetEpoch` parameter would be misleading and was dropped. Uses the      view selection core (no settle-on-miss), so under stale (over-stated) leaves this may      diverge from the state-changing `_generateChallenge` draw, which self-heals — best-effort      prediction only, not guaranteed between settle cycles (RFC §Security).","kaId":"     Selected Knowledge Asset id within that CG."}},"pruneExpiredKnowledgeAssets(uint256,uint256,uint256)":{"details":"Commits in its OWN transaction, independently of `createChallenge`      (whose settle/prune work rolls back on an all-miss revert), so a      clogged CG is always recoverable. Safe to be permissionless: it can      ONLY remove already-expired (sampling-ineligible) KAs — never a live      one — so there is no griefing vector; a caller merely spends its own      gas cleaning dead slots. `swapRemoveSamplingKnowledgeAssetAt` preserves      `kaToContextGraph`, so readers (`getKAContextGraphId`) and the      double-registration guard stay intact. Gas is bounded by `maxScan`;      a large flood is cleared across several calls. `startIndex` lets a      caller target any region — e.g. the expired TAIL of a CG with a long      live prefix, which a fixed from-0 scan with a small `maxScan` would      never reach. (Reading the list to choose `startIndex` is an off-chain      `eth_call`; this on-chain method just acts on the window.)","params":{"cgId":"context graph to clean.","maxScan":"max list positions to examine this call.","startIndex":"first list position to examine (0 = from the head)."},"returns":{"removed":"number of expired KAs swap-popped."}},"setProofingPeriodDurationInBlocks(uint16)":{"details":"Sets the duration of proofing periods in blocks with a one-epoch delay Only contracts registered in the Hub can call this function If a pending change exists, replaces it; otherwise adds a new duration Changes take effect in the next epoch to ensure smooth transitions","params":{"durationInBlocks":"New proofing period duration in blocks (must be > 0)"}},"submitProof(bytes,bytes32[])":{"details":"Submits proof for an active challenge to earn score used for later reward calculation Public CG path — verifies a V10 flat-KA Merkle inclusion proof (dkg-core `V10MerkleTree` / spec §9.0.2): `leaf` is a `hashTripleV10` public leaf or a private sub-root leaf; `challenge.chunkId` stores the challenged leaf index in the sorted+deduped bottom layer; `merkleProof` is the sibling path produced by `V10MerkleTree.proof(leafIndex)`. Curated CG path (OT-RFC-49) — same `_verifyV10MerkleProof` sibling-pair composition over a different leaf/root pair: `leaf` is `hashTripleV10(s,p,o)` of the challenged PUBLIC `_catalog` triple at index `challenge.chunkId`, and the root is the per-KA catalog root (`getCatalogRoot`) snapshotted at issuance. Cores hold zero private bytes post-strip, so they prove the public catalog, never the ciphertext. `_verifyV10MerkleProof` is unchanged — only the (root, leaf, count) triple differs between the two paths. Root/count source: the (root, leafCount) pair is PINNED on the challenge at issuance (`_generateChallenge`). `submitProof` reads NO live getter, so a KA update mid-period cannot rotate the challenge surface out from under an honest prover (Trap 1), and the pinned root also captures the exact branch / KA-store / generation the leaf was drawn against (subsumes the R3 seam). Sharding-table check: `nodeExistsInShardingTable` is universal membership today. RFC-39 §5.2 calls for tightening to per-CG `isHostForCG(identityId, cgId)` once `ShardingTableStorage` ships that view (and once per-CG sub-sharding lands in the v2 of RFC-38). Under universal-hosting (Phase A.5), the universal check is functionally equivalent — every active core hosts every KA's substrate."},"updateAndGetActiveProofPeriodStartBlock()":{"details":"Updates and returns the current active proof period start block Automatically advances to the next period if the current one has ended","returns":{"_0":"Current active proof period start block number"}},"version()":{"details":"Returns the version of this contract Used for contract identification and versioning"}},"version":1},"userdoc":{"errors":{"ChallengeDrawPaused()":[{"notice":"Thrown by `_generateChallenge` while the BIT weight index is backfill-locked         (`CGWeightTreeStorage.backfillLocked()`). Open on a clean deploy (deploy step `057`         unlocks at deploy, fresh ledger); only held during an upgrade-in-place that seeds         existing CGs into the tree. While locked, the node retries on a later proof period."}],"NoEligibleContextGraph()":[{"notice":"Thrown by `_generateChallenge` when no active CG (public or         curated) holds non-zero per-epoch value at the current epoch —         i.e. there is nothing eligible to challenge against. The caller's         transaction reverts and the node retries on the next proof period."}],"NoEligibleKnowledgeAsset()":[{"notice":"Thrown by `_generateChallenge` when the chosen CG's KA list is         empty or all sampled KAs are expired after `MAX_KA_RETRIES`         attempts. Same retry-next-period semantics as above."}]},"events":{"ChallengeGenerated(uint72,uint256,uint256,uint256,uint256,uint256)":{"notice":"Emitted when {createChallenge} produces a new challenge for a         node. Off-chain consumers (node UI, indexers) use the indexed         `cgId` to know which Context Graph the challenge targets — this         information is intentionally NOT stored on the Challenge struct         to keep its on-chain footprint unchanged."}},"kind":"user","methods":{"MAX_CG_RETRIES()":{"notice":"RFC-39 Phase A.5 — bounded retries at the CG selection layer         when the picked CG has no challengeable KA (all legacy /         uncommitted curated KAs, or every retry hit an expired KA).         Falls through to a fresh weighted draw with the picked CG         excluded, instead of reverting the whole sampling tick and         letting one high-value legacy curated CG DoS the network."},"MAX_KA_RETRIES()":{"notice":"Maximum number of in-CG resamples when the picker hits an         expired KA during Phase 10 weighted challenge generation.         Exhausting this budget reverts with `NoEligibleKnowledgeAsset`         so the node skips the current proof period and retries on the         next one (see {_pickKa})."},"cgWeightTreeStorage()":{"notice":"Phase 10.x — Fenwick/BIT index over CG ids for O(log) value-weighted         challenge selection (replaces the O(N·D) twin scan). See         docs/rfcs/scalable-weighted-cg-sampling.md."},"pruneExpiredKnowledgeAssets(uint256,uint256,uint256)":{"notice":"Permissionless keeper: prune EXPIRED Knowledge Assets from a CG's         COMPACTED sampling list (`_samplingKAList`). New entries are         appended on registration but never removed there, so expired KAs         accumulate as dead slots and can starve the bounded within-CG draw         (`MAX_KA_RETRIES`). Scans up to `maxScan` positions and swap-pops         every entry whose `endEpoch < currentEpoch`. The append-only         registration list the reconciler reads is left untouched."}},"version":1}},"settings":{"compilationTarget":{"contracts/RandomSampling.sol":"RandomSampling"},"evmVersion":"london","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[],"viaIR":true},"sources":{"@openzeppelin/contracts/access/Ownable.sol":{"content":"// SPDX-License-Identifier: MIT
