        bytes32 root,
        bytes32 leaf,
        uint256 leafIndex,
        bytes32[] calldata proof
    ) internal pure returns (bool) {
        bytes32 h = leaf;
        uint256 idx = leafIndex;
        for (uint256 i = 0; i < proof.length; ) {
            bytes32 sib = proof[i];
            if (idx % 2 == 0) {
                h = keccak256(abi.encodePacked(h, sib));
            } else {
                h = keccak256(abi.encodePacked(sib, h));
            }
            unchecked {
                idx = idx / 2;
                ++i;
            }
        }
        return h == root;
    }

