pragma solidity ^0.8.20;

import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {Chronos} from "./Chronos.sol";
import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

/**
 * @title ContextGraphValueStorage
 * @notice Lightweight per-CG and global per-epoch TRAC value tracker for V10
 *         value-weighted challenges. Mirrors `EpochStorage.sol` diff/cumulative
 *         finalize pattern at lines 149-174 / 279-310 exactly, but scaled to
 *         int256/uint256 because publish values are wei-of-TRAC and exceed uint96.
 *
 * Design rationale (see V10_CONTRACTS_REDESIGN_v2.md §"Data in
 * ContextGraphValueStorage"): a KA published with value `V` for `lifetime`
 * epochs contributes `V / lifetime` per epoch during its active window
 * [startEpoch, startEpoch + lifetime - 1]. Expiry is handled implicitly by the
 * negative diff written at `startEpoch + lifetime`. No cleanup, no keeper.
 *
 * `addCGValueForEpochRange` uses plain integer division per the spec. A couple
 * wei of rounding dust per publish is acceptable — this mapping is used for
 * challenge weighting, not reward distribution.
 *
 * The dormant shard mappings (`cgShard`, `shardKnowledgeValue`) are reserved
 * storage slots for future V11 sharding. Setters will be added alongside the
 * V11 logic contracts; no API exists today.
 */
contract ContextGraphValueStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "ContextGraphValueStorage";
    string private constant _VERSION = "10.0.2";

    event CGValueAddedForEpochRange(
        uint256 indexed cgId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint256 lifetime,
        uint256 value,
        uint256 perEpoch
    );
    event CGValueFinalized(uint256 indexed cgId, uint256 startEpoch, uint256 endEpoch);
    event GlobalValueFinalized(uint256 startEpoch, uint256 endEpoch);

    error ZeroLifetime();
    error ZeroValue();
    error NegativeCumulative();
    error BackfillForbidden();
    error FutureOrCurrentEpoch();

    Chronos public chronos;

    // Per-CG diff/cumulative ledgers.
    mapping(uint256 cgId => mapping(uint256 epoch => int256)) public cgValueDiff;
    mapping(uint256 cgId => mapping(uint256 epoch => uint256)) public cgValueCumulative;
    mapping(uint256 cgId => uint256) public cgLastFinalizedEpoch;

    // Global diff/cumulative ledgers (sum across all CGs).
    mapping(uint256 epoch => int256) public totalValueDiff;
    mapping(uint256 epoch => uint256) public totalValueCumulative;
    uint256 public globalLastFinalizedEpoch;

    /// @dev Reserved storage slots for future V11 sharding. Setters will be
    ///      added alongside the V11 logic contracts; no API exists today.
    mapping(uint256 cgId => uint256) public cgShard;
    mapping(uint256 shardId => mapping(uint256 epoch => uint256)) public shardKnowledgeValue;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function initialize() public onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    // -------------------------------------------------------------------------
    // State mutators
    // -------------------------------------------------------------------------

    /**
     * @notice Record that `value` TRAC will be paid for `cgId` spread evenly
     *         across `lifetime` epochs starting at `startEpoch`. Each epoch in
     *         [startEpoch, startEpoch + lifetime - 1] receives `value/lifetime`.
     * @dev Mirrors `EpochStorage.addTokensToEpochRange`. Finalizes per-CG and
     *      global ledgers up to `currentEpoch - 1` after the diff writes so
     *      stale epochs are crystallized before the next read. Rounding dust is
     *      discarded per the spec (challenge weighting, not reward payout).
     *
     *      Invariant: `startEpoch >= currentEpoch`. Backfilling into an
     *      already-finalized epoch would corrupt `cgValueCumulative` silently
     *      because the cumulative at that epoch has already been crystallized
     *      and subsequent reads hit the fast path. Reverts `BackfillForbidden`
     *      if the caller tries.
     *
     *      Retraction / expiry is automatic via the paired negative diff
     *      written at `startEpoch + lifetime`. There is no removal function
     *      by design: Phase 8 value-changing ops (CREATE, byte-size-grow
     *      UPDATE, lifetime extension) are all positive deltas, and natural
     *      expiry is handled by the diff ledger itself.
     */
    function addCGValueForEpochRange(
        uint256 cgId,
        uint256 startEpoch,
        uint256 lifetime,
        uint256 value
    ) external onlyContracts {
        if (lifetime == 0) {
            revert ZeroLifetime();
        }
        if (value == 0) {
            revert ZeroValue();
        }

        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (startEpoch < currentEpoch) {
            revert BackfillForbidden();
        }

        uint256 perEpoch = value / lifetime;
        int256 perEpochSigned = SafeCast.toInt256(perEpoch);

        cgValueDiff[cgId][startEpoch] += perEpochSigned;
        cgValueDiff[cgId][startEpoch + lifetime] -= perEpochSigned;

        totalValueDiff[startEpoch] += perEpochSigned;
        totalValueDiff[startEpoch + lifetime] -= perEpochSigned;

        if (currentEpoch > 1) {
            _finalizeCGValueUpTo(cgId, currentEpoch - 1);
            _finalizeGlobalValueUpTo(currentEpoch - 1);
        }

        emit CGValueAddedForEpochRange(
            cgId,
            startEpoch,
            startEpoch + lifetime - 1,
            lifetime,
            value,
            perEpoch
        );
    }

    /**
     * @notice Crystallizes `cgValueCumulative[cgId]` up to `epoch` so
     *         subsequent reads at or below `epoch` become O(1). Safe to call
     *         repeatedly: a call with `epoch <= cgLastFinalizedEpoch[cgId]`
     *         is a no-op.
     * @dev Intended to be called by RandomSampling before a challenge draw
     *      (see V10_CONTRACTS_REDESIGN_v2 "On challenge generation"), but any
     *      Hub-registered contract may call it. Reads stay pure `view`; this
     *      is the state-changing half of the "finalize then read" pattern.
     * @dev Reverts FutureOrCurrentEpoch if `epoch` is at or beyond the current
     *      epoch. Only past epochs may be finalized; current-epoch reads always
     *      take the simulation path to reflect in-flight diff writes.
     */
    function finalizeCGValueUpTo(uint256 cgId, uint256 epoch) external onlyContracts {
        if (epoch >= chronos.getCurrentEpoch()) {
            revert FutureOrCurrentEpoch();
        }
        if (epoch <= cgLastFinalizedEpoch[cgId]) {
            return;
        }
        _finalizeCGValueUpTo(cgId, epoch);
    }

    /**
     * @notice Crystallizes `totalValueCumulative` up to `epoch`. See
     *         {finalizeCGValueUpTo} for semantics.
     * @dev Reverts FutureOrCurrentEpoch if `epoch` is at or beyond the current
     *      epoch. Only past epochs may be finalized; current-epoch reads always
     *      take the simulation path to reflect in-flight diff writes.
     */
    function finalizeGlobalValueUpTo(uint256 epoch) external onlyContracts {
        if (epoch >= chronos.getCurrentEpoch()) {
            revert FutureOrCurrentEpoch();
        }
        if (epoch <= globalLastFinalizedEpoch) {
            return;
        }
        _finalizeGlobalValueUpTo(epoch);
    }

    // -------------------------------------------------------------------------
    // Read helpers
    // -------------------------------------------------------------------------

    /// @notice Active per-epoch contribution of `cgId` at `epoch` (sum of all
    ///         active KAs' per-epoch values at that epoch). Returns the
    ///         simulated value if the epoch has not been finalized yet.
    function getCGValueAtEpoch(uint256 cgId, uint256 epoch) public view returns (uint256) {
        if (epoch <= cgLastFinalizedEpoch[cgId]) {
            return cgValueCumulative[cgId][epoch];
        }
        return _simulateCGValueFinalization(cgId, epoch);
    }

    /// @notice Global sum across all CGs of active per-epoch contributions at `epoch`.
    function getTotalValueAtEpoch(uint256 epoch) public view returns (uint256) {
        if (epoch <= globalLastFinalizedEpoch) {
            return totalValueCumulative[epoch];
        }
        return _simulateGlobalValueFinalization(epoch);
    }

    function getCurrentCGValue(uint256 cgId) external view returns (uint256) {
        return getCGValueAtEpoch(cgId, chronos.getCurrentEpoch());
    }

    function getCurrentTotalValue() external view returns (uint256) {
        return getTotalValueAtEpoch(chronos.getCurrentEpoch());
    }

    // -------------------------------------------------------------------------
    // Internal finalization
    // -------------------------------------------------------------------------

    function _finalizeCGValueUpTo(uint256 cgId, uint256 epoch) internal {
        uint256 lastFinalized = cgLastFinalizedEpoch[cgId];
        if (epoch <= lastFinalized) {
            return;
        }

        uint256 startEpoch = lastFinalized + 1;
        int256 running;
        if (lastFinalized > 0) {
            running = int256(cgValueCumulative[cgId][lastFinalized]);
        }

        for (uint256 e = startEpoch; e <= epoch; e++) {
            running += cgValueDiff[cgId][e];
            // Cumulative values are non-negative by construction (positive diffs
            // at startEpoch are always matched by negative diffs at
            // startEpoch+lifetime). Revert defensively on underflow.
            if (running < 0) {
                revert NegativeCumulative();
            }
            cgValueCumulative[cgId][e] = uint256(running);
        }

        cgLastFinalizedEpoch[cgId] = epoch;

        emit CGValueFinalized(cgId, startEpoch, epoch);
    }

    function _finalizeGlobalValueUpTo(uint256 epoch) internal {
        uint256 lastFinalized = globalLastFinalizedEpoch;
        if (epoch <= lastFinalized) {
            return;
        }

        uint256 startEpoch = lastFinalized + 1;
        int256 running;
        if (lastFinalized > 0) {
            running = int256(totalValueCumulative[lastFinalized]);
        }

        for (uint256 e = startEpoch; e <= epoch; e++) {
            running += totalValueDiff[e];
            if (running < 0) {
                revert NegativeCumulative();
            }
            totalValueCumulative[e] = uint256(running);
        }

        globalLastFinalizedEpoch = epoch;

        emit GlobalValueFinalized(startEpoch, epoch);
    }

    function _simulateCGValueFinalization(uint256 cgId, uint256 epoch) internal view returns (uint256) {
        uint256 lastFinalized = cgLastFinalizedEpoch[cgId];
        if (epoch <= lastFinalized) {
            return cgValueCumulative[cgId][epoch];
        }

        int256 running;
        if (lastFinalized > 0) {
            running = int256(cgValueCumulative[cgId][lastFinalized]);
        }

        for (uint256 e = lastFinalized + 1; e <= epoch; e++) {
            running += cgValueDiff[cgId][e];
            // Unify policy with the mutate path (`_finalizeCGValueUpTo`): a
            // negative running total would signal ledger corruption and is an
            // unrecoverable invariant break. Reverting here — even from a view
            // function — gives RPC clients immediate visibility instead of
            // silently clamping to zero.
            if (running < 0) {
                revert NegativeCumulative();
            }
        }

        return uint256(running);
    }

    function _simulateGlobalValueFinalization(uint256 epoch) internal view returns (uint256) {
        uint256 lastFinalized = globalLastFinalizedEpoch;
        if (epoch <= lastFinalized) {
            return totalValueCumulative[epoch];
        }

        int256 running;
        if (lastFinalized > 0) {
            running = int256(totalValueCumulative[lastFinalized]);
        }

        for (uint256 e = lastFinalized + 1; e <= epoch; e++) {
            running += totalValueDiff[e];
            if (running < 0) {
                revert NegativeCumulative();
            }
        }

        return uint256(running);
    }
}
","keccak256":"0x672a3540bac7f8d4f74a2dca2610d6254f800e6f468ce8ea4d1f5a8738ee092c","license":"Apache-2.0"},"contracts/storage/ConvictionStakingStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Chronos} from "./Chronos.sol";
import {Guardian} from "../Guardian.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubLib} from "../libraries/HubLib.sol";
import {StakingLib} from "../libraries/StakingLib.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title ConvictionStakingStorage
 * @notice Primary accounting store AND TRAC vault for V10 staking.
 *
 * V10 architecture (post-consolidation, v4.0.0):
 *   - CSS is the single source of truth for V10 staking: NFT-keyed positions,
 *     per-node stake aggregates, per-epoch operator-fee/net-rewards flags,
 *     per-node operator-fee balances + withdrawal queue, AND the TRAC vault.
 *     There is no separate `StakingStorage` in the V10 hot path.
 *   - The TRAC custody role moved here from V8 `StakingStorage` in v4.0.0:
 *     CSS now extends `Guardian`, so its `tokenContract` reference and
 *     `transferStake` outflow function come from the same base every V10
 *     publish/payment contract uses for vault-routed deposits. Vault-target
 *     consumers (`KnowledgeAssetsLifecycle`, `DKGKnowledgeAssets`, `Paymaster`,
 *     `PublishingConvictionAccount`, `DKGPublishingConvictionNFT`,
 *     `DKGStakingConvictionNFT`) resolve `hub.getContractAddress("ConvictionStakingStorage")`
 *     for both deposits (TRAC `transferFrom` to CSS) and withdrawals
 *     (`StakingV10` calls `cs.transferStake`).
 *   - Migration to V10 is MANDATORY: every V8 delegator becomes a V10 NFT
 *     position. `RandomSampling.calculateNodeScore` therefore reads the
 *     timestamp-accurate effective stake here (raw TRAC × active conviction
 *     multipliers), while raw stake gates still read `nodeStakeV10`. V8
 *     `StakingStorage` is deployed-but-unused dead code post-consolidation;
 *     only `StakingV10._convertToNFT` reads it (V8→V10 drain at cutover).
 *
 * Rewards model (D19 — compound-into-raw):
 *   - The previous split-bucket model (separate `rewards` sidecar that
 *     always earned 1x) has been removed. Claimed rewards compound into
 *     `raw`, so they take on the position's current lock multiplier.
 *   - `cumulativeRewardsClaimed` is now a statistic-only counter for
 *     UI/indexer consumption; it never enters effective-stake math.
 *
 * Tier model (D20 — mutable wall-clock tier ladder):
 *   - Tier durations and multipliers are stored in `_tiers` (keyed by
 *     `lockTier` id). The baseline ladder seeded at `initialize()` is
 *     {0→(0s, 1x), 1→(30d, 1.5x), 3→(90d, 2x), 6→(180d, 3.5x), 12→(366d, 6x)}.
 *   - `expiryTimestamp = block.timestamp + duration`, rounded UP to the
 *     next 12-hour expiry bucket. The upward rounding keeps the promised
 *     minimum lock duration while coalescing per-block dust stakes into
 *     one queue slot per half-day.
 *   - New tiers can be appended via `addTier` (HubOwner or multisig owner).
 *     Existing tiers can be deactivated via `deactivateTier` to stop
 *     accepting NEW fresh stakes, but relock / migration paths still
 *     honor the original commitment (existence-only check). The model is
 *     additive-only: once added a tier id cannot be removed.
 *
 * Effective-stake accounting (D26 — timestamp-accurate):
 *   - Each node carries a `runningNodeEffectiveStake[id]` settled at
 *     `nodeLastSettledAt[id]`, plus a sorted queue of pending boost-
 *     expiry drops (`nodeExpiryTimes[id]` / `nodeExpiryDrop[id][ts]`)
 *     with a monotonic head cursor `nodeExpiryHead[id]`.
 *   - `settleNodeTo(id, ts)` advances the running stake to `ts` by
 *     draining all expiry entries whose timestamp is <= ts. Called by
 *     every CSS mutator before applying its own delta, and by
 *     `RandomSampling.submitProof` before integrating score.
 *   - This replaces the v2.x epoch-diff accumulator (effectiveStakeDiff,
 *     nodeEffectiveStakeDiff, lastFinalizedEpoch, finalize*). Past-epoch
 *     effective-stake snapshots are no longer reconstructable from CSS;
 *     consumers that need them should settle and read "current" state.
 */
contract ConvictionStakingStorage is INamed, IVersioned, Guardian {
    using SafeERC20 for IERC20;

    string private constant _NAME = "ConvictionStakingStorage";
    // Version history:
    //   1.1.0 — split-bucket rewards, discrete tier ladder.
    //   1.2.0 — V10-native pending-withdrawal storage (create/delete/get).
    //   2.0.0 — V10 canonical store (positions + per-node aggregates +
    //           absorbed DelegatorsInfo + tier constants).
    //   2.1.0 — Mutable D20 tier ladder (lockTier rename, _tiers mapping).
    //   2.2.0 — D14/D25 atomic-withdraw & in-place redelegate (removed
    //           PendingWithdrawal).
    //   3.0.0 — D26 timestamp-accurate effective-stake accounting:
    //           * `Position.expiryEpoch` → `Position.expiryTimestamp`
    //             (uint40 seconds-since-unix-epoch, NOT a Chronos epoch).
    //           * Per-node running effective-stake with a sorted pending-
    //             expiry queue. Epoch-diff accumulator, finalize helpers
    //             and their dirty cursors removed.
    //           * `BLOCK_DRIFT_BUFFER` removed (no longer meaningful).
    //   3.1.0 — D26 code-review follow-ups:
    //           * M1 — `updateOnRelock` removed; `createNewPositionFromExisting`
    //             simplified to same-identity-only (cross-identity branch was
    //             unreachable — `redelegate` goes through `updateOnRedelegate`).
    //           * M2 — `nodeExpiryPresent` mapping added so a cancel→reschedule
    //             at the same `ts` doesn't duplicate the queue slot.
    //           * M3/M4 — `addTier` rejects degenerate tier configs
    //             (tier 0 must be rest state; non-zero tier needs both a
    //             positive duration and a >1x multiplier).
    //           * L4 — `createPosition` guards against `currentEpoch == 0`.
    //           * L5 — `_cancelNodeExpiry` `delete`s the slot when the
    //             remaining drop hits zero (refunds SSTORE).
    //           * L7 — `getNodeEffectiveStakeAtEpoch` tolerates Chronos
    //             returning 0 for unanchored epochs.
    //           * L9 — `setV10LaunchEpoch` is one-shot (anchor cannot be
    //             silently rebound).
    //           * L11 — `createPosition` no longer takes `multiplier18`;
    //             it reads the multiplier from the tier table.
    //   4.0.0 — Storage consolidation: CSS absorbs the TRAC vault role and
    //           operator-fee accounting from V8 `StakingStorage`.
    //           * Base contract switched from `HubDependent` → `Guardian`
    //             (CSS now holds `tokenContract`, exposes `transferStake`,
    //             and inherits the misplaced-token rescue helpers).
    //           * Added `nodeOperatorFeeBalance` (per-node fee accrual the
    //             `StakingV10._claim` operator split previously wrote to
    //             `StakingStorage.nodes[id].operatorFeeBalance`).
    //           * Added `operatorFeeWithdrawals` (per-node request queue
    //             with the V8 `StakeWithdrawalRequest` struct shape so the
    //             `StakingV10` admin surface can be added without further
    //             struct churn).
    //           * Vault deposits across V10 (`KnowledgeAssetsV10`,
    //             `DKGKnowledgeAssets`, `Paymaster`, etc.) now route TRAC
    //             into the CSS address. `StakingStorage` is no longer in
    //             the V10 hot path; only `StakingV10._convertToNFT` reads
    //             it (V8→V10 drain at cutover).
    //   4.1.0 — V8→V10 migration conviction credit.
    //           * `createPosition` gains a sixth parameter
    //             `expiryShortenedBy` (seconds). Subtracted from the
    //             tier-default `expiryTimestamp` after the standard
    //             computation so callers (presently
    //             `StakingV10._convertToNFT`) can grant a one-time time
    //             credit to V8 delegators who held continuous stake for
    //             the 60 days preceding V10 launch. Validated against
    //             `_tierDuration(lockTier)` and the current block
    //             timestamp; tier-0 callers MUST pass 0.
    //   10.0.3 — Reward carries (audit fix: mid-epoch redelegate/relock
    //           orphaned the current epoch's settled delegator score).
    //           * NEW `RewardCarry` struct + `rewardCarries` mapping:
    //             pointers to RSS (epoch, identityId, delegatorKey) score
    //             slots that the position's CURRENT node/key no longer
    //             reaches. Written by `StakingV10.redelegate` / `relock`,
    //             drained by `StakingV10._claim`.
    //           * `createNewPositionFromExisting` migrates carries across
    //             the relock burn-mint; `deletePosition` deletes them.
    //   10.0.5 — Expiry-queue DoS hardening:
    //           * Boost expiries are rounded up to 12-hour buckets so
    //             per-block dust stakes coalesce into one queue slot per
    //             half-day.
    //           * New distinct expiry slots are capped per node; same-bucket
    //             stakes keep coalescing even when the cap is reached.
    //   10.0.6 — Audit G-6: increaseRaw/decreaseRaw install a position's running-
    //             stake / boost contribution as the ONE-SHOT delta from its raw
    //             (floor(newRaw*m) - floor(oldRaw*m)), so a reward-compounded
    //             position's contribution always equals the one-shot value the
    //             unwind paths remove. This eliminates the incremental-vs-one-shot
    //             floor asymmetry that bricked redelegate/relock/exit/decreaseRaw,
    //             with the strict cancel/stake-delta invariants kept intact.
    string private constant _VERSION = "10.0.6";

    // Multiplier scale, matches DKGStakingConvictionNFT._convictionMultiplier
    // (returns 1e18-scaled values so fractional tiers like 1.5x and 3.5x
    // are representable).
    uint256 internal constant SCALE18 = 1e18;
    uint40 public constant EXPIRY_BUCKET_SECONDS = 12 hours;
    uint256 public constant MAX_NODE_PENDING_EXPIRIES = 1024;
    /// @notice Maximum boosted lock-tier duration. Bounded so the distinct future
    ///         buckets a node can ever hold stays STRICTLY below the slot cap.
    ///         Because `_computeExpiryTimestamp` rounds UP to the next bucket, a
    ///         tier of `k` buckets created just after a boundary expires `k + 1`
    ///         buckets out — so a node staking once per bucket can reach `k + 1`
    ///         distinct pending slots. To keep that `<= MAX_NODE_PENDING_EXPIRIES`,
    ///         a tier must be at most `MAX_NODE_PENDING_EXPIRIES - 1` buckets
    ///         (`1023 * 12h = 511.5 days`). With this enforced in `addTier`,
    ///         `MAX_NODE_PENDING_EXPIRIES` can never be reached by valid stakes —
    ///         it stays a pure backstop and never blocks a legitimate stake/relock
    ///         (and the tombstone-vs-live slot distinction can never bite). The
    ///         baseline ladder tops out at 366 days, well under this.
    uint256 public constant MAX_TIER_DURATION =
        (MAX_NODE_PENDING_EXPIRIES - 1) * uint256(EXPIRY_BUCKET_SECONDS);

    // ============================================================
    //                 D20 — Mutable tier ladder
    // ============================================================

    // Tier definition. `duration` is the committed wall-clock lock
    // (seconds) passed to `_computeExpiryTimestamp`. `multiplier18` is the
    // 1e18-scaled effective-stake multiplier applied pre-expiry.
    //
    // `active` gates NEW fresh stakes (createPosition with migrationEpoch==0).
    // Relock and migration paths take the existence-only path so the user's
    // original commitment is honored even if a tier has since been retired.
    //
    // `exists` distinguishes a never-added tier id from a deactivated one.
    struct TierConfig {
        uint256 duration;
        uint64 multiplier18;
        bool active;
        bool exists;
    }

    // Position layout (two storage slots — V10 compound-into-raw model):
    //   slot 1: raw(96) + lockTier(40) + expiryTimestamp(40) + identityId(72) = 248 bits
    //   slot 2: cumulativeRewardsClaimed(96) + multiplier18(64)
    //           + lastClaimedEpoch(32) + migrationEpoch(32)                 = 224 bits
    //
    // Field semantics:
    //   raw                        — principal (+ compounded rewards). Earns
    //                                `multiplier18` while `block.timestamp <
    //                                expiryTimestamp`, drops back to 1x
    //                                thereafter. Claim compounds TRAC into
    //                                this field.
    //   lockTier                   — tier identifier from the mutable ladder
    //                                in `_tiers`. Baseline set is
    //                                {0, 1, 3, 6, 12} (30d / 90d / 180d /
    //                                366d wall-clock locks).
    //   expiryTimestamp            — Unix timestamp (seconds) at which the
    //                                boost drops. 0 iff lockTier == 0 (rest
    //                                state). uint40 holds ~34k years.
    //   identityId                 — the node this position delegates to.
    //   cumulativeRewardsClaimed   — D19 statistic: total TRAC ever compounded
    //                                into `raw` via claim for this NFT.
    //   multiplier18               — materialized copy of `_tierMultiplier(lockTier)`.
    //   lastClaimedEpoch           — Chronos epoch of the last successful claim.
    //   migrationEpoch             — D6: V8→V10 retroactive-claim boundary.
    //                                0 means "fresh V10 stake".
    struct Position {
        uint96 raw;
        uint40 lockTier;
        uint40 expiryTimestamp;
        uint72 identityId;
        // slot 2
        uint96 cumulativeRewardsClaimed;
        uint64 multiplier18;
        uint32 lastClaimedEpoch;
        uint32 migrationEpoch;
    }

    event PositionCreated(
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint96 raw,
        uint40 lockTier,
        uint40 expiryTimestamp,
        uint64 multiplier18,
        uint32 migrationEpoch
    );
    event PositionRedelegated(
        uint256 indexed tokenId,
        uint72 indexed oldIdentityId,
        uint72 indexed newIdentityId
    );
    event PositionDeleted(uint256 indexed tokenId);
    // D21+D23 — ephemeral NFT for `relock` only. The old tokenId is burned
    // and a fresh one is minted under a new tier. Off-chain indexers trace a
    // position's history across the burn-mint via the (oldTokenId, newTokenId)
    // link in this event.
    event PositionReplaced(
        uint256 indexed oldTokenId,
        uint256 indexed newTokenId,
        uint72 indexed newIdentityId,
        uint96 raw,
        uint40 newLockTier,
        uint40 newExpiryTimestamp,
        uint64 newMultiplier18
    );
    event LastClaimedEpochUpdated(uint256 indexed tokenId, uint32 epoch);
    event MigrationEpochSet(uint256 indexed tokenId, uint32 epoch);
    // D19 — compound-into-raw model.
    event RawIncreased(uint256 indexed tokenId, uint96 amount, uint96 newRaw);
    event RawDecreased(uint256 indexed tokenId, uint96 amount, uint96 newRaw);
    event CumulativeRewardsClaimedUpdated(uint256 indexed tokenId, uint96 added, uint96 newTotal);
    // D26 — running-effective-stake settlement.
    event NodeEffectiveStakeSettled(
        uint72 indexed identityId,
        uint40 fromTimestamp,
        uint40 toTimestamp,
        uint256 newRunningEffectiveStake
    );
    event NodeEffectiveStakeDelta(uint72 indexed identityId, int256 delta, uint256 newRunningEffectiveStake);
    event NodeExpiryScheduled(uint72 indexed identityId, uint40 timestamp, uint256 dropAdded, uint256 newTotalDrop);
    event NodeExpiryCancelled(uint72 indexed identityId, uint40 timestamp, uint256 dropRemoved, uint256 newTotalDrop);
    error NodeExpiryQueueFull(uint72 identityId, uint256 pending, uint256 maxPending);
    // D15 — V10 stake aggregate events.
    event NodeStakeV10Increased(uint72 indexed identityId, uint256 amount, uint256 newNodeStake, uint256 newTotal);
    event NodeStakeV10Decreased(uint72 indexed identityId, uint256 amount, uint256 newNodeStake, uint256 newTotal);
    // D7 — V10 launch marker.
    event V10LaunchEpochSet(uint256 epoch);
    // D3 — DelegatorsInfo-absorbed events.
    event IsOperatorFeeClaimedForEpochUpdated(uint72 indexed identityId, uint256 indexed epoch, bool isClaimed);
    event NetNodeEpochRewardsSet(uint72 indexed identityId, uint256 indexed epoch, uint256 amount);

    Chronos public chronos;

    mapping(uint256 => Position) public positions;

    // ============================================================
    //    D26 — Running effective-stake state per node
    // ============================================================
    //
    // Invariant: `runningNodeEffectiveStake[id]` is the node's effective
    // stake AT `nodeLastSettledAt[id]` (inclusive). All expiries whose
    // timestamp is <= nodeLastSettledAt[id] have already been applied
    // (dropped from the running stake). All entries in `nodeExpiryTimes[id]`
    // at indices >= nodeExpiryHead[id] have timestamps strictly greater
    // than nodeLastSettledAt[id].
    // Slither: mappings are zero-initialized by the language — see
    // ContextGraphStorage._participantAgents for the long-form rationale.
    // slither-disable-next-line uninitialized-state
    mapping(uint72 => uint256) public runningNodeEffectiveStake;
    // slither-disable-next-line uninitialized-state
    mapping(uint72 => uint40) public nodeLastSettledAt;

    // Sorted-ascending queue of pending boost-expiry timestamps per node.
    // We only append past index `nodeExpiryHead[id]`; partially-cancelled
    // entries stay physically present at their sorted position and drain
    // with whatever drop remains. Fully-cancelled entries (drop back to 0
    // before drain) are kept as "zero-drop" slots so that when a fresh
    // expiry lands at the same `ts`, `nodeExpiryPresent` prevents us from
    // pushing a duplicate (M2).
    mapping(uint72 => uint40[]) internal nodeExpiryTimes;
    // Aggregate boost drop scheduled at exactly `ts` for `id`. Multiple
    // positions sharing an `expiryTimestamp` are coalesced here.
    mapping(uint72 => mapping(uint40 => uint256)) internal nodeExpiryDrop;
    // Drain cursor into `nodeExpiryTimes[id]`. Entries below the head
    // are fully drained and MUST NOT be read again.
    mapping(uint72 => uint256) internal nodeExpiryHead;
    // M2 — tracks whether `ts` has a live slot in `nodeExpiryTimes[id]`
    //      at or past `nodeExpiryHead[id]`. Set on first schedule, cleared
    //      when the drain cursor walks past the slot. Without this, a
    //      cancel-to-zero followed by a fresh schedule at the same `ts`
    //      would push a second entry (functionally harmless, but doubles
    //      the SSTOREs and weakens the "at most one entry per `ts`"
    //      invariant on `nodeExpiryTimes[id]`).
    mapping(uint72 => mapping(uint40 => bool)) internal nodeExpiryPresent;

    // ============================================================
    //                D5 — Per-node tokenId enumeration
    // ============================================================
    mapping(uint72 => uint256[]) public nodeTokens;
    mapping(uint72 => mapping(uint256 => uint256)) public nodeTokenIndex;

    // ============================================================
    //           D15 — V10 stake aggregates (raw TRAC principal)
    // ============================================================
    mapping(uint72 => uint256) public nodeStakeV10;
    uint256 public totalStakeV10;

    // ============================================================
    //            D3 — Absorbed DelegatorsInfo fields (V10)
    // ============================================================
    mapping(uint72 => mapping(uint256 => bool)) public isOperatorFeeClaimedForEpoch;
    mapping(uint72 => mapping(uint256 => uint256)) public netNodeEpochRewards;

    // ============================================================
    //   v4.0.0 — Operator-fee balance + withdrawal queue (absorbed
    //            from V8 StakingStorage)
    //
    // `nodeOperatorFeeBalance` accrues each time `StakingV10._claim`
    // splits gross node rewards by `Profile.getLatestOperatorFeePercentage`
    // (operator-fee-percentage cut, drained when the operator finalises a
    // `requestOperatorFeeWithdrawal` / `cancelOperatorFeeWithdrawal` against
    // their identity).
    //
    // `operatorFeeWithdrawals` is the per-identity request queue. The struct
    // shape is reused from `StakingLib.StakeWithdrawalRequest` so the
    // operator-side admin functions can be added on `StakingV10` (or on a
    // future thin admin contract) without further struct churn. V10 never
    // populates `indexedOutAmount`; it stays 0 for every entry.
    // ============================================================
    mapping(uint72 => uint96) public nodeOperatorFeeBalance;
    mapping(uint72 => StakingLib.StakeWithdrawalRequest) public operatorFeeWithdrawals;

    // ============================================================
    //                 D7 — V10 launch epoch marker
    // ============================================================
    uint256 public v10LaunchEpoch;

    // ============================================================
    //   V8→V10 "pool & allocate" migration credit ledger
    // ============================================================
    // Migrated-but-unallocated TRAC, per delegator. Backed 1:1 by TRAC
    // physically held in THIS contract (moved here by the drain worker via
    // StakingStorage.transferStake). The only sink is `spendMigrationCredit`
    // (driven by DKGStakingConvictionNFT.allocate) — credit is NEVER
    // withdrawable to a wallet. Lives here (durable storage), not on the
    // wrapper (logic), so a wrapper redeploy mid-migration cannot strand the
    // already-moved TRAC.
    mapping(address => uint96) public migrationCredit;
    // Lock-shortening (seconds) applied to ANY tier-6/12 migration allocation
    // (universal — no per-staker eligibility distinction). Set
    // at cutover via `setConvictionCreditSeconds`, capped below the shortest
    // credited-tier (tier 6) duration so a position's expiry cannot underflow.
    // 0 until set (no credit).
    uint40 public convictionCreditSeconds;

    // ============================================================
    //           D20 (v2.1.0) — Mutable tier-ladder storage
    // ============================================================
    mapping(uint40 => TierConfig) internal _tiers;
    uint40[] public tierIds;

    // ============================================================
    //   v10.0.3 — Reward carries (mid-epoch redelegate / relock)
    // ============================================================
    //
    // A mid-epoch `redelegate` flips `pos.identityId`, and a `relock`
    // re-keys the position under a fresh tokenId. In both cases the
    // delegator score already settled in RandomSamplingStorage under the
    // OLD (epoch, identityId, delegatorKey) slot becomes unreachable from
    // `StakingV10._claim`, which reads only the position's CURRENT node +
    // key — silently forfeiting up to one epoch's rewards. Each carry is
    // a POINTER to such a slot; the score value itself stays in RSS.
    // `StakingV10._claim` integrates matured carries (epoch closed) and
    // clears them.
    struct RewardCarry {
        uint72 identityId;
        uint32 epoch;
        bytes32 delegatorKey;
    }

    // Bounded so a position's claim/withdraw can never be self-bricked by
    // an excessive number of same-epoch redelegations (carries from past
    // epochs are flushed on every claim).
    uint256 public constant MAX_REWARD_CARRIES = 32;

    mapping(uint256 => RewardCarry[]) internal rewardCarries;

    event RewardCarryAdded(
        uint256 indexed tokenId,
        uint72 indexed identityId,
        uint32 epoch,
        bytes32 delegatorKey
    );
    event RewardCarriesCleared(uint256 indexed tokenId, uint32 maxEpoch, uint256 removed);

    // ============================================================
    //          Tier admin events (v2.1.0)
    // ============================================================
