        return operatorFeeWithdrawals[identityId].amount != 0;
    }

    // ============================================================
    //   v4.0.0 — TRAC vault outflow
    //
    // The CSS contract address is the V10 TRAC vault (deposits arrive via
    // `transferFrom(staker, address(this), amount)` from publish/staking
    // callers). `transferStake` (stake movement) and `transferRegistrationDepositFee`
    // (OT-RFC-53 escrow treasury fee) are the outflow paths; both gated to Hub-
    // registered contracts, mirroring V8 `StakingStorage.transferStake`.
    // ============================================================

    function transferStake(address receiver, uint96 stakeAmount) external onlyContracts {
        // Slither: `safeTransfer` (SafeERC20) reverts on failure rather than
        // returning false — the "unchecked-transfer" pattern Slither flags
        // applies to the bare ERC20 `.transfer()` return-value path. This
        // call site is the SAFE wrapper precisely BECAUSE the V10 design
        // upgraded V8's bare `.transfer()` (see StakingStorage.transferStake)
        // to SafeERC20. False positive — kept here as a directive for
        // future maintainers debugging the report.
        // slither-disable-next-line unchecked-transfer
        tokenContract.safeTransfer(receiver, stakeAmount);
        emit StakedTokensTransferred(receiver, stakeAmount);
    }

    /// @notice OT-RFC-53: routes the protocol treasury fee owed on an escrow-funded
    ///         publish/update/extend out of the vault to `treasury`. The SECOND
    ///         vault-outflow path; mirrors {transferStake} (gated to Hub contracts,
    ///         SafeERC20). The caller (KnowledgeAssetsLifecycle) computes `amount`
    ///         (bounded by the consumed escrow) and passes the configured
    ///         `protocolTreasury`; CSS performs only the gated transfer.
    function transferRegistrationDepositFee(address treasury, uint96 amount) external onlyContracts {
        // slither-disable-next-line unchecked-transfer
        tokenContract.safeTransfer(treasury, amount);
        emit RegistrationDepositFeeTransferred(treasury, amount);
    }

    // ============================================================
    //                       Internal helpers
    // ============================================================

    /**
     * @dev Wall-clock expiry computation (D26). Boosts last at least the tier
     *      duration and expire on the next 12-hour bucket. Returns 0 for tier-0
     *      (permanent rest state).
     */
    function _computeExpiryTimestamp(uint40 lockTier) internal view returns (uint40) {
        if (lockTier == 0) return 0;
        uint256 duration = _tierDuration(lockTier);
        uint256 exp = block.timestamp + duration;
        return _bucketExpiryTimestamp(exp);
    }

    function _bucketExpiryTimestamp(uint256 rawExpiry) internal pure returns (uint40) {
        uint256 bucket = uint256(EXPIRY_BUCKET_SECONDS);
        uint256 bucketed = ((rawExpiry + bucket - 1) / bucket) * bucket;
        require(bucketed <= type(uint40).max, "Expiry overflow");
        return uint40(bucketed);
    }

    function _pushNodeToken(uint72 identityId, uint256 tokenId) internal {
        nodeTokenIndex[identityId][tokenId] = nodeTokens[identityId].length;
        nodeTokens[identityId].push(tokenId);
    }

    function _popNodeToken(uint72 identityId, uint256 tokenId) internal {
        uint256[] storage arr = nodeTokens[identityId];
        uint256 idx = nodeTokenIndex[identityId][tokenId];
        uint256 last = arr.length - 1;
        if (idx != last) {
            uint256 movedToken = arr[last];
            arr[idx] = movedToken;
            nodeTokenIndex[identityId][movedToken] = idx;
        }
        arr.pop();
        delete nodeTokenIndex[identityId][tokenId];
    }

    function _increaseNodeStakeV10(uint72 identityId, uint256 amount) internal {
        nodeStakeV10[identityId] += amount;
        totalStakeV10 += amount;
        emit NodeStakeV10Increased(identityId, amount, nodeStakeV10[identityId], totalStakeV10);
    }

    function _decreaseNodeStakeV10(uint72 identityId, uint256 amount) internal {
        nodeStakeV10[identityId] -= amount;
        totalStakeV10 -= amount;
        emit NodeStakeV10Decreased(identityId, amount, nodeStakeV10[identityId], totalStakeV10);
    }
}
","keccak256":"0x52c35cbd4d06b4765f837089b13202cd1cca5023be8df9e481cdc00892acaa62","license":"Apache-2.0"},"contracts/storage/DKGKnowledgeAssets.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Guardian} from "../Guardian.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {KnowledgeAssetLib} from "../libraries/KnowledgeAssetLib.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubDependent} from "../abstract/HubDependent.sol";

/**
 * @title DKGKnowledgeAssets
 * @notice Greenfield KA storage: one ERC-721 per Knowledge Asset (`tokenId == kaId`),
 *         merkle-root history, economics, and ciphertext commitments. No ERC-1155.
 */
contract DKGKnowledgeAssets is INamed, IVersioned, HubDependent, ERC721, Guardian {

    /// @dev `author` is the verified agent identity from the V10.1+
    ///      author-attestation EIP-712 envelope, or `address(0)` for legacy
    ///      callers (`KnowledgeAsset (V10.1 active path)`) that do not perform author
    ///      attestation. Indexers SHOULD prefer this `indexed` field over
    ///      walking storage when filtering KAs by author.
    event KnowledgeAssetCreated(
        uint256 indexed id,
        address indexed author,
        string publishOperationId,
        bytes32 merkleRoot,
        uint88 byteSize,
        uint40 startEpoch,
        uint40 endEpoch,
        uint96 tokenAmount,
        bool isImmutable
    );
    event KnowledgeAssetUpdated(
        uint256 indexed id,
        address indexed author,
        string updateOperationId,
        bytes32 merkleRoot,
        uint256 byteSize,
        uint96 tokenAmount
    );
    event KnowledgeAssetsMinted(uint256 indexed id, address indexed to, uint256 startId, uint256 endId);
    event KnowledgeAssetsBurned(uint256 indexed id, address indexed from, uint256[] tokenIds);
    event KnowledgeAssetPublisherUpdated(uint256 indexed id, address publisher);
    event KnowledgeAssetMerkleRootsUpdated(uint256 indexed id, KnowledgeAssetLib.MerkleRoot[] merkleRoots);
    event KnowledgeAssetMerkleRootAdded(uint256 indexed id, bytes32 merkleRoot);
    event KnowledgeAssetMerkleRootRemoved(uint256 indexed id, bytes32 merkleRoot);
    event KnowledgeAssetMintedUpdated(uint256 indexed id, uint256 minted);
    event KnowledgeAssetBurnedUpdated(uint256 indexed id, uint256[] burned);
    event KnowledgeAssetByteSizeUpdated(uint256 indexed id, uint256 byteSize);
    event KnowledgeAssetChunksAmountUpdated(uint256 indexed id, uint256 chunksAmount);
    event KnowledgeAssetTokenAmountUpdated(uint256 indexed id, uint256 tokenAmount);
    event KnowledgeAssetStartEpochUpdated(uint256 indexed id, uint256 startEpoch);
    event KnowledgeAssetEndEpochUpdated(uint256 indexed id, uint256 endEpoch);
    event URIUpdate(string newURI);

    /// @notice OT-RFC-49 / WS-B: a per-KA PUBLIC `_catalog` commitment was set for
    ///         curated random sampling. Emitted by `setCatalogCommitment`, called by
    ///         `KnowledgeAssetsLifecycle._executePublishCore` immediately after
    ///         `createKnowledgeAsset` when the publish input carries a non-zero
    ///         `(catalogRoot, catalogLeafCount)` pair AND the owning CG is curated.
    ///         Off-chain indexers consume this to know which KAs participate in the
    ///         curated-CG sampling lottery (the picker treats missing commitments as
    ///         "skip this KA").
    event KnowledgeAssetCatalogCommitmentSet(
        uint256 indexed id,
        bytes32 catalogRoot,
        uint32 catalogLeafCount
    );

    // --- OT-RFC-43 Option 1 (variant 1a) errors ---
    /// @notice The supplied packed `kaId`'s high 160 bits (`kaId >> 96`) do not
    ///         equal the attested author. A wallet may only mint KAs within its
    ///         own namespace (OT-RFC-43 §4).
    error KaIdNamespaceMismatch(uint256 kaId, address author);
    /// @notice The supplied (author, number) packs to a `kaId` that is already
    ///         minted — a re-used reservation. Never a silent clobber.
    error KaIdAlreadyMinted(uint256 kaId);
    /// @notice `getLatestKnowledgeAssetId` is deprecated under Option 1 — ids
    ///         are packed (author<<96)|number and not globally sequential, so a
    ///         single "latest id" is meaningless.
    error GetLatestKnowledgeAssetIdDeprecated();

    string private constant _NAME = "DKGKnowledgeAssets";
    string private constant _VERSION = "10.1.0";

    string private _tokenURI;

    uint256 public immutable KNOWLEDGE_ASSET_BATCH_MAX_SIZE;

    // OT-RFC-43 Option 1 (variant 1a): the global auto-increment id counter is
    // retired — KA ids are now caller-supplied packed (author<<96)|number values
    // minted in `createKnowledgeAsset`. This storage SLOT is retained (renamed,
    // never written) so the layout of every field below is unchanged whether
    // this contract is freshly deployed OR upgraded in place (R3 — proxy-vs-
    // redeploy is unresolved; keeping the gap is safe under both). Do not
    // repurpose without resolving R3.
    // slither-disable-next-line unused-state,constable-states
    uint256 private _deprecatedKnowledgeAssetsCounter;
    uint256 private _totalMintedKnowledgeAssetsCounter;
    // V10 retired burn semantics — `burnKnowledgeAssetsTokens` is a
    // `pure` revert stub — so this counter is intentionally never
    // written. Solidity zero-initializes it, and `totalBurned()`
    // correctly returns 0 for legacy ABI consumers. The Slither
    // directive silences the rule WITHOUT changing storage layout;
    // making this `constant` would shift every slot declared below
    // and is out of scope for an ABI-only legacy field.
    // slither-disable-next-line uninitialized-state
    uint256 private _totalBurnedKnowledgeAssetsCounter;

    uint96 private _totalTokenAmount;

    mapping(uint256 => KnowledgeAssetLib.KnowledgeAsset) public knowledgeAssets;
    mapping(uint256 => bool) public isKnowledgeAssetBurned;

    /// @dev Parallel mapping for V10.1+ author attestation.
    ///
    /// Why a parallel map and not a struct field on `MerkleRoot`:
    /// `KnowledgeAsset.merkleRoots` is a dynamic array, so
    /// extending its element struct from 3 to 4 storage slots would
    /// shift the slot stride of every prior root entry — already-
    /// deployed KAs would decode their historical
    /// `publisher`/`merkleRoot`/`timestamp` from the wrong offsets.
    /// Layout-preserving fix: keep `MerkleRoot` at 3 slots and store
    /// the EIP-712-recovered author identity at
    /// `merkleRootAuthors[kaId][rootIndex]`. Both the publish AND the
    /// update path persist a verified EIP-712 author here (OT-RFC-45
    /// owner-only update). `address(0)` means the state change at
    /// `rootIndex` did not carry an attestation — i.e. legacy V8/V9
    /// mutations and admin paths (`setMerkleRoots` / `pushMerkleRoot`,
    /// which zero the slot by design).
    /// Indexers SHOULD prefer the indexed `author` topic on
    /// `KnowledgeAssetCreated` / `KnowledgeAssetUpdated`
    /// events; this on-chain mapping is the canonical lookup for
    /// `/api/knowledge-assets/:id/author` and SPARQL author-filter queries.
    mapping(uint256 => mapping(uint256 => address)) public merkleRootAuthors;

    /// @notice OT-RFC-49: DEAD — slot preserved for storage-layout stability.
    ///
    /// Formerly `ciphertextChunksRoots` (RFC-39 Phase A.5 curated ciphertext
    /// commitment). RFC-49 ("hosting follows access") strips private ciphertext
    /// from cores entirely, so cores can no longer prove a ciphertext chunk —
    /// the curated random-sampling commitment is now the PUBLIC `_catalog` root
    /// (`catalogRoots` below). This slot is intentionally retained (not deleted)
    /// so that removing it cannot shift the base slot of `_authorKaNumberHighWater`
    /// or any later mapping; same discipline as `_deprecatedKnowledgeAssetsCounter`.
    /// Never read or written after RFC-49.
    mapping(uint256 => bytes32) private _deprecatedCiphertextChunksRoots;

    /// @notice OT-RFC-49: DEAD — slot preserved. Formerly `ciphertextChunkCounts`.
    /// See `_deprecatedCiphertextChunksRoots`. Superseded by `catalogLeafCounts`.
    mapping(uint256 => uint32) private _deprecatedCiphertextChunkCounts;

    /// @notice OT-RFC-43 Option 1 (variant 1a): per-author high-water KA `number`
    ///         (the low 96 bits of the packed kaId), stored as `maxNumber + 1` so
    ///         the default `0` unambiguously means "this author has never minted".
    ///         Lets the off-chain allocator reconcile its cold-start floor with a
    ///         single O(1) `getMaxKaNumberForAuthor` view instead of an unbounded
    ///         `KnowledgeAssetCreated` log scan (which overflows the `eth_getLogs`
    ///         block-range cap on networks with deep history). Appended at the END
    ///         of storage to preserve the slot layout of every field above (see the
    ///         layout note on `_deprecatedKnowledgeAssetsCounter`).
    mapping(address => uint256) private _authorKaNumberHighWater;

    /// @notice OT-RFC-49 / WS-B: per-KA PUBLIC `_catalog` Merkle root — the curated
    ///         random-sampling commitment that replaces the stripped ciphertext one.
    ///
    /// Used by `RandomSampling._pickWeightedChallenge` (eligibility + leaf draw) and
    /// `RandomSampling.submitProof` for curated CGs in place of the ciphertext root.
    /// The root commits ONLY to the public `_catalog` leaves of the latest publish —
    /// the same plaintext triples cores host and serve under
    /// `did:dkg:context-graph:<cgId>/_catalog`. Computed off-chain by
    /// `computeCatalogRoot` (a dedicated `V10MerkleTree` over the catalog quads only;
    /// the private sub-roots stay in `merkleRoots[]` for proof-of-existence but are
    /// NEVER drawn). Set by `KnowledgeAssetsLifecycle._executePublishCore` for curated
    /// CGs. Default `bytes32(0)` is the "no catalog commitment" sentinel that
    /// `RandomSampling` uses to skip this KA in the curated draw (legacy KAs read 0 →
    /// grandfathered out until they re-publish post-RFC-49).
    ///
    /// Appended at the END of storage (after `_authorKaNumberHighWater`) to preserve
    /// every existing slot; new slot space cannot masquerade old ciphertext roots as
    /// catalog roots.
    mapping(uint256 => bytes32) public catalogRoots;

    /// @notice OT-RFC-49 / WS-B: per-KA PUBLIC `_catalog` leaf count (POST sort+dedupe,
    ///         == `V10MerkleTree.leafCount`, NOT the raw catalog-quad count).
    ///
    /// The leaf-count input for the `chunkId = uint256(seed) % count` draw in
    /// `RandomSampling._pickWeightedChallenge` step 3 for curated CGs, and the bounds
    /// check in `submitProof`. Must equal the off-chain tree's `leafCount` exactly or
    /// an honest prover cannot build a proof for a drawn `chunkId`.
    mapping(uint256 => uint32) public catalogLeafCounts;

    constructor(
        address hubAddress,
        uint256 _knowledgeAssetBatchMaxSize,
        string memory uri
    ) ERC721("DKG Knowledge Asset", "DKA") Guardian(hubAddress) {
        KNOWLEDGE_ASSET_BATCH_MAX_SIZE = _knowledgeAssetBatchMaxSize;
        _tokenURI = uri;
    }

    function name() public pure virtual override(INamed, ERC721) returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual returns (string memory) {
        return _VERSION;
    }

    function knowledgeAssetBatchMaxSize() external view returns (uint256) {
        return KNOWLEDGE_ASSET_BATCH_MAX_SIZE;
    }

    function createKnowledgeAsset(
        address publisher,
        address author,
        uint256 kaId,
        string calldata publishOperationId,
        bytes32 merkleRoot,
        uint256 knowledgeAssetsAmount,
        uint88 byteSize,
        uint40 startEpoch,
        uint40 endEpoch,
        uint96 tokenAmount,
        bool isImmutable,
        uint32 merkleLeafCount
    ) external onlyContracts returns (uint256) {
        if (knowledgeAssetsAmount != 1) {
            revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, knowledgeAssetsAmount, 1);
        }

        // OT-RFC-43 Option 1 (variant 1a): the KA id is supplied by the caller
        // (the off-chain allocator) as a deterministic packed value
        // kaId = (uint160(author) << 96) | uint96(number). The high 160 bits
        // MUST equal the attested author, so a wallet can only mint within its
        // own namespace. Unforgeable: `author` is proven by the EIP-712
        // attestation in `KnowledgeAssetsLifecycle._verifyAuthorAttestation`
        // before this call. NB: the namespace binds to the attested AUTHOR
        // (EIP-712 signer / initial NFT owner), a deliberate divergence from
        // OT-RFC-43 §7's `msg.sender`/publisher diagram — the two coincide in
        // the dominant self-publish case. The global `++_knowledgeAssetsCounter`
        // is removed under 1a (packed-only; no post-tx canonical id).
        if ((kaId >> 96) != uint256(uint160(author))) {
            revert KaIdNamespaceMismatch(kaId, author);
        }
        // Fail fast on a re-used (author, number): the id must not already be
        // minted. `_safeMint` below would also revert, but checking here keeps
        // checks-effects-interactions ordering (no state mutation before the
        // guard) and surfaces a precise error. `kaId` is guaranteed non-zero
        // because `author != address(0)` (enforced upstream), so the `0`
        // sentinel used by `getKnowledgeAssetId` / `isPartOfKnowledgeAsset` is
        // never produced here.
        if (_ownerOf(kaId) != address(0)) {
            revert KaIdAlreadyMinted(kaId);
        }
        // Defense-in-depth (audit hardening): assert the KA struct slot is
        // pristine, not merely unowned. `_ownerOf` proves the token was never
        // minted, but `onlyContracts` setters (`setMerkleRoots` / `pushMerkleRoot`)
        // could in principle pre-seed `knowledgeAssets[kaId]` for an unminted id,
        // which would make the index-0 `merkleRootAuthors` write below land at the
        // wrong index. Under the retired `++_knowledgeAssetsCounter` scheme a fresh
        // id was structurally never-touched; with caller-supplied ids we assert it.
        if (knowledgeAssets[kaId].merkleRoots.length != 0) {
            revert KaIdAlreadyMinted(kaId);
        }

        uint256 knowledgeAssetId = kaId;

        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[knowledgeAssetId];

        ka.merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // First root of a fresh KA — index 0. `kaId` was just proven unminted
        // above (and `_safeMint` re-enforces it), so this parallel slot is
        // empty; the unconditional shape is kept for parity with
        // `updateKnowledgeAsset` below, where the index can have been
        // previously used (post-pop).
        merkleRootAuthors[knowledgeAssetId][ka.merkleRoots.length - 1] = author;
        ka.byteSize = byteSize;
        ka.startEpoch = startEpoch;
        ka.endEpoch = endEpoch;
        ka.tokenAmount = tokenAmount;
        ka.isImmutable = isImmutable;
        ka.merkleLeafCount = merkleLeafCount;

        unchecked {
            _totalTokenAmount += tokenAmount;
        }

        ka.minted = 1;
        _totalMintedKnowledgeAssetsCounter += 1;

        // OT-RFC-43 Option 1: record the per-author high-water `number` BEFORE the
        // `_safeMint` interaction (checks-effects-interactions — `_safeMint` calls
        // `onERC721Received` on a contract recipient). Stored as `number + 1` so the
        // default 0 means "never minted"; only ever raised, never lowered, so a
        // gap-filling mint of a lower number can never regress the floor. Backs the
        // O(1) `getMaxKaNumberForAuthor` allocator reconcile.
        uint256 mintedNumber = uint96(knowledgeAssetId); // low 96 bits = per-author number
        if (mintedNumber + 1 > _authorKaNumberHighWater[author]) {
            _authorKaNumberHighWater[author] = mintedNumber + 1;
        }

        _safeMint(author, knowledgeAssetId);

        emit KnowledgeAssetCreated(
            knowledgeAssetId,
            author,
            publishOperationId,
            merkleRoot,
            byteSize,
            startEpoch,
            endEpoch,
            tokenAmount,
            isImmutable
        );

        return knowledgeAssetId;
    }

    /// @notice OT-RFC-43 Option 1 (variant 1a): the highest KA `number` already
    ///         minted under `author` (the low 96 bits of its packed kaId), or `-1`
    ///         if `author` has never minted a KA.
    /// @dev    O(1) replacement for enumerating `KnowledgeAssetCreated(id, author)`
    ///         logs. The off-chain allocator's next number for `author` is
    ///         `getMaxKaNumberForAuthor(author) + 1`, so a brand-new author (result
    ///         `-1`) correctly starts at number 0. Returns `int256` so "never minted"
    ///         is a true sentinel rather than colliding with a legitimately-minted
    ///         number 0.
    ///
    ///         PRECONDITION — not backfilled across an in-place storage upgrade.
    ///         `_authorKaNumberHighWater` is only populated by `createKnowledgeAsset`
    ///         from this version (10.0.4) onward. On a fresh deploy or redeploy — the
    ///         expected path, where every KA is minted under this contract — it is
    ///         authoritative for ALL of an author's KAs. But if this storage is
    ///         upgraded IN PLACE over a pre-10.0.4 deployment that already minted KAs,
    ///         those historical authors read `-1` until their next mint. Such an
    ///         in-place upgrade is not supported unless the mapping is backfilled or
    ///         the allocator is explicitly configured to reconcile historical mints by
    ///         another source. The repository deployment flow is a fresh asset-storage
    ///         redeploy/Hub rotation, not bytecode replacement over existing storage.
    /// @param  author The attested author address (the high 160 bits of a packed kaId).
    /// @return The highest KA `number` already minted under `author`, or `-1` if none.
    function getMaxKaNumberForAuthor(address author) external view returns (int256) {
        uint256 highWater = _authorKaNumberHighWater[author];
        return highWater == 0 ? int256(-1) : int256(highWater) - 1;
    }

    function getKnowledgeAsset(
        uint256 id
    ) external view returns (KnowledgeAssetLib.KnowledgeAsset memory) {
        return knowledgeAssets[id];
    }

    /// @dev `author` is the verified author identity for this update. The
    ///      V10.1 update path attests the author (EIP-712) and enforces
    ///      owner-only in `KnowledgeAssetsLifecycle._executeUpdateCore`
    ///      (OT-RFC-45), so callers on that path pass a non-zero, verified
    ///      author. `address(0)` only on admin/legacy paths that carry no
    ///      attestation.
    function updateKnowledgeAsset(
        address publisher,
        address author,
        uint256 id,
        string calldata updateOperationId,
        bytes32 merkleRoot,
        uint256 mintKnowledgeAssetsAmount,
        uint256[] calldata knowledgeAssetsToBurn,
        uint88 byteSize,
        uint96 tokenAmount,
        uint32 merkleLeafCount
    ) external onlyContracts {
        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[id];

        unchecked {
            _totalTokenAmount = _totalTokenAmount - ka.tokenAmount + tokenAmount;
        }

        ka.merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // Unconditional overwrite — this index may have been written by
        // a previous create/update and then popped via `popMerkleRoot`,
        // leaving the stale author in the parallel slot. Always write
        // the current `author` (the verified EIP-712 author the V10.1
        // lifecycle update path supplies; `address(0)` only on admin/legacy
        // paths) to make the canonical mapping monotonic with the
        // merkleRoots array.
        merkleRootAuthors[id][ka.merkleRoots.length - 1] = author;
        ka.byteSize = byteSize;
        ka.tokenAmount = tokenAmount;
        ka.merkleLeafCount = merkleLeafCount;

        // Burn with an empty list is a no-op (the inner for-loop over
        // tokenIds skips when length == 0). Mint with amount == 0 was
        // previously unconditionally dispatched to `_mintWithoutCheck`,
        // which reverts `MintZeroQuantity` on zero — blocking true
        // metadata-only updates (delta == 0, no mint, no burn) that the
        // KnowledgeAssetsV10 update flow explicitly documents as
        // supported. Guard the mint call so metadata-only rotations work
        // end-to-end. See Codex review round 2, finding 6.
        if (mintKnowledgeAssetsAmount != 0 || knowledgeAssetsToBurn.length != 0) {
            revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(
                id,
                ka.minted,
                mintKnowledgeAssetsAmount,
                0
            );
        }

        emit KnowledgeAssetUpdated(id, author, updateOperationId, merkleRoot, byteSize, tokenAmount);
    }

    /// @notice Lightweight update-path metadata — scalar fields only + the
    /// pre-update merkle-root count. Intended for callers (e.g.
    /// `KnowledgeAssetsV10._executeUpdateCore`) that need the state
    /// summary but NOT the full history arrays.
    ///
    /// Problem: `getKnowledgeAssetMetadata` performs a full
    /// storage → memory struct copy, which walks every entry of
    /// `merkleRoots[]` and `burned[]`. Because both arrays grow
    /// monotonically on every update, the memory cost (and thus gas
    /// cost) of calling that getter from the update path itself scales
    /// linearly — actually super-linearly due to EVM memory-expansion
    /// quadratic term — with the number of prior updates. A KA with
    /// thousands of historical entries eventually becomes un-updatable.
    ///
    /// This getter returns only the scalar slots and the merkle-root
    /// chain length (as a plain `uint256`), so the update path's gas
    /// cost is constant regardless of history.
    ///
    /// Codex review round 3 finding 1.
    function getKnowledgeAssetUpdateContext(
        uint256 id
    )
        external
        view
        returns (
            uint256 merkleRootsCount,
            uint256 minted,
            uint88 byteSize,
            uint40 endEpoch,
            uint96 tokenAmount,
            bool isImmutable,
            uint32 merkleLeafCount
        )
    {
        KnowledgeAssetLib.KnowledgeAsset storage ka = knowledgeAssets[id];
        return (
            ka.merkleRoots.length,
            ka.minted,
            ka.byteSize,
            ka.endEpoch,
            ka.tokenAmount,
            ka.isImmutable,
            ka.merkleLeafCount
        );
    }

    /// @notice Leaf count for the V10 flat-KA Merkle tree at latest root
    ///         (see `merkleLeafCount` on `KnowledgeAsset`).
    function getMerkleLeafCount(uint256 id) external view returns (uint32) {
        return knowledgeAssets[id].merkleLeafCount;
    }

    /// @notice OT-RFC-49 / WS-B: write the curated PUBLIC `_catalog` commitment for
    ///         a freshly-created (or updated) KA. Caller must enforce the curated-CG
    ///         gate — KAS does not look at `ContextGraphStorage` to keep the storage
    ///         layer policy-free.
    ///
    ///         Both fields must be non-zero — partial commitments (a non-zero root
    ///         with zero count, or vice versa) are forbidden because they would
    ///         silently de-rail the picker (zero count → divide-by-zero in the
    ///         catalog-leaf draw, zero root → proof verification against an empty
    ///         tree). `KnowledgeAssetsLifecycle` normalises "no commitment" to a
    ///         literal no-call (no event emitted, both slots stay at default zero).
    ///         Unlike the stripped ciphertext commitment, the catalog commitment is
    ///         re-set on every curated update so the random-sampling surface tracks
    ///         the latest published `_catalog`.
    function setCatalogCommitment(
        uint256 id,
        bytes32 catalogRoot,
        uint32 catalogLeafCount
    ) external onlyContracts {
        require(
            catalogRoot != bytes32(0) && catalogLeafCount > 0,
            "Invalid catalog commitment"
        );
        catalogRoots[id] = catalogRoot;
        catalogLeafCounts[id] = catalogLeafCount;

        emit KnowledgeAssetCatalogCommitmentSet(id, catalogRoot, catalogLeafCount);
    }

    /// @notice OT-RFC-49 / WS-B: latest PUBLIC `_catalog` Merkle root for a curated
    ///         KA, or `bytes32(0)` if no commitment was ever set (public KA, or a
    ///         legacy curated KA that has not re-published since RFC-49).
    ///         `RandomSampling` treats the zero sentinel as "skip this KA in the
    ///         curated draw".
    function getCatalogRoot(uint256 id) external view returns (bytes32) {
        return catalogRoots[id];
    }

    /// @notice OT-RFC-49 / WS-B: PUBLIC `_catalog` leaf count for a curated KA, or
    ///         `0` if no commitment was ever set. Used as the leaf-count input for
    ///         the curated picker's `chunkId = seed % count` draw and as the bounds
    ///         check in `submitProof`. Equals the off-chain `V10MerkleTree.leafCount`
    ///         (post sort+dedupe), never the raw catalog-quad count.
    function getCatalogLeafCount(uint256 id) external view returns (uint32) {
        return catalogLeafCounts[id];
    }

    function getKnowledgeAssetMetadata(
        uint256 id
    )
        external
        view
        returns (
            KnowledgeAssetLib.MerkleRoot[] memory,
            uint256[] memory,
            uint256,
            uint88,
            uint40,
            uint40,
            uint96,
            bool
        )
    {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];

        return (
            ka.merkleRoots,
            ka.burned,
            ka.minted,
            ka.byteSize,
            ka.startEpoch,
            ka.endEpoch,
            ka.tokenAmount,
            ka.isImmutable
        );
    }

    /// @dev Greenfield: batch mint/burn removed. Updates rotate merkle state only.
    function mintKnowledgeAssetsTokens(uint256, address, uint256) public pure {
        revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, 1, 0);
    }

    function burnKnowledgeAssetsTokens(uint256, address, uint256[] calldata) public pure {
        revert KnowledgeAssetLib.ExceededKnowledgeAssetBatchSize(0, 0, 1, 0);
    }

    function getMerkleRoots(uint256 id) external view returns (KnowledgeAssetLib.MerkleRoot[] memory) {
        return knowledgeAssets[id].merkleRoots;
    }

    function setMerkleRoots(
        uint256 id,
        KnowledgeAssetLib.MerkleRoot[] memory _merkleRoots
    ) external onlyContracts {
        // Wholesale replacement — clear the parallel author mapping for
        // the union of old and new index ranges so stale authors from
        // either side cannot leak through. The MerkleRoot struct itself
        // carries no author field (parallel-mapping design), so callers
        // of this admin path cannot supply authors here; effective
        // post-condition is "all entries unauthenticated until a
        // subsequent create/update writes them". Loop bounded by the
        // larger of the two lengths.
        uint256 oldLen = knowledgeAssets[id].merkleRoots.length;
        uint256 newLen = _merkleRoots.length;
        uint256 maxLen = oldLen > newLen ? oldLen : newLen;
        for (uint256 i = 0; i < maxLen; i++) {
            delete merkleRootAuthors[id][i];
        }
        knowledgeAssets[id].merkleRoots = _merkleRoots;

        emit KnowledgeAssetMerkleRootsUpdated(id, _merkleRoots);
    }

    function getMerkleRootObjectByIndex(
        uint256 id,
        uint256 index
    ) external view returns (KnowledgeAssetLib.MerkleRoot memory) {
        return knowledgeAssets[id].merkleRoots[index];
    }

    function getMerkleRootByIndex(uint256 id, uint256 index) external view returns (bytes32) {
        return knowledgeAssets[id].merkleRoots[index].merkleRoot;
    }

    function getMerkleRootPublisherByIndex(uint256 id, uint256 index) external view returns (address) {
        return knowledgeAssets[id].merkleRoots[index].publisher;
    }

    function getMerkleRootTimestampByIndex(uint256 id, uint256 index) external view returns (uint256) {
        return knowledgeAssets[id].merkleRoots[index].timestamp;
    }

    function getLatestMerkleRootObject(uint256 id) external view returns (KnowledgeAssetLib.MerkleRoot memory) {
        return _safeGetLatestMerkleRootObject(id);
    }

    function getLatestMerkleRoot(uint256 id) external view returns (bytes32) {
        return _safeGetLatestMerkleRootObject(id).merkleRoot;
    }

    function getLatestMerkleRootPublisher(uint256 id) external view returns (address) {
        return _safeGetLatestMerkleRootObject(id).publisher;
    }

    function getLatestMerkleRootTimestamp(uint256 id) external view returns (uint256) {
        return _safeGetLatestMerkleRootObject(id).timestamp;
    }

    function getMerkleRootAuthorByIndex(uint256 id, uint256 index) external view returns (address) {
        // Bounds-check via the canonical merkleRoots array so out-of-range
        // queries revert the same way as the other index-based getters,
        // rather than silently returning address(0) from the parallel
        // mapping (which has no concept of "valid index").
        require(index < knowledgeAssets[id].merkleRoots.length, "Index out of bounds");
        return merkleRootAuthors[id][index];
    }

    /// @notice Verified author identity for the latest merkle-root entry
    /// of `id`. Returns `address(0)` if the latest state change did not
    /// carry an author attestation (legacy/admin path only; both the publish
    /// and the V10.1 update path now attest the author — OT-RFC-45). Used by
    /// `/api/get` and other off-chain readers as the
    /// canonical "who authored this KA" lookup — chain wins over any
    /// off-chain `dkg:authoredBy` triple.
    function getLatestMerkleRootAuthor(uint256 id) external view returns (address) {
        uint256 len = knowledgeAssets[id].merkleRoots.length;
        if (len == 0) return address(0);
        return merkleRootAuthors[id][len - 1];
    }

    function pushMerkleRoot(address publisher, uint256 id, bytes32 merkleRoot) external onlyContracts {
        knowledgeAssets[id].merkleRoots.push(
            KnowledgeAssetLib.MerkleRoot(publisher, merkleRoot, block.timestamp)
        );
        // Defensive clear: this index may have been used by a previously
        // popped author entry (`merkleRoots.length` cycles via push/pop).
        // Without the explicit `delete`, an unauthenticated push after a
        // pop would inherit the popped entry's author and `getLatestMerkleRootAuthor`
        // would lie. Legacy `pushMerkleRoot` carries no author by design —
        // always zero the parallel slot.
        delete merkleRootAuthors[id][knowledgeAssets[id].merkleRoots.length - 1];

        emit KnowledgeAssetMerkleRootAdded(id, merkleRoot);
    }

    function popMerkleRoot(uint256 id) external onlyContracts {
        uint256 oldLen = knowledgeAssets[id].merkleRoots.length;
        bytes32 latestMerkleRoot = _safeGetLatestMerkleRootObject(id).merkleRoot;
        knowledgeAssets[id].merkleRoots.pop();
        // Clear the parallel author slot for the popped index. Without
        // this, the slot survives and a later push at the same index can
        // resurrect a stale author. `oldLen > 0` guards the empty-array
        // case (pop on empty would have reverted on the line above; the
        // `_safeGetLatestMerkleRootObject` returns a zero-tuple but the
        // pop itself reverts on length 0 — kept defensive).
        if (oldLen > 0) {
            delete merkleRootAuthors[id][oldLen - 1];
        }

        emit KnowledgeAssetMerkleRootRemoved(id, latestMerkleRoot);
    }

    function getMinted(uint256 id) external view returns (uint256) {
        return knowledgeAssets[id].minted;
    }

    function setMinted(uint256 id, uint256 _minted) external onlyContracts {
        knowledgeAssets[id].minted = _minted;

        emit KnowledgeAssetMintedUpdated(id, _minted);
    }

    function getBurned(uint256 id) external view returns (uint256[] memory) {
        return knowledgeAssets[id].burned;
    }

    function getBurnedAmount(uint256 id) external view returns (uint256) {
        return knowledgeAssets[id].burned.length;
    }

    function setBurned(uint256 id, uint256[] calldata _burned) external onlyContracts {
        knowledgeAssets[id].burned = _burned;

        emit KnowledgeAssetBurnedUpdated(id, _burned);
    }

    function getByteSize(uint256 id) external view returns (uint88) {
        return knowledgeAssets[id].byteSize;
    }

    function setByteSize(uint256 id, uint88 _byteSize) external onlyContracts {
        knowledgeAssets[id].byteSize = _byteSize;

        emit KnowledgeAssetByteSizeUpdated(id, _byteSize);
    }

    function getTokenAmount(uint256 id) external view returns (uint96) {
        return knowledgeAssets[id].tokenAmount;
    }

    function setTokenAmount(uint256 id, uint96 _tokenAmount) external onlyContracts {
        _totalTokenAmount = _totalTokenAmount - knowledgeAssets[id].tokenAmount + _tokenAmount;
        knowledgeAssets[id].tokenAmount = _tokenAmount;

        emit KnowledgeAssetTokenAmountUpdated(id, _tokenAmount);
    }

    function getStartEpoch(uint256 id) external view returns (uint40) {
        return knowledgeAssets[id].startEpoch;
    }

    function setStartEpoch(uint256 id, uint40 _startEpoch) external onlyContracts {
        knowledgeAssets[id].startEpoch = _startEpoch;

        emit KnowledgeAssetStartEpochUpdated(id, _startEpoch);
    }

    function getEndEpoch(uint256 id) external view returns (uint40) {
        return knowledgeAssets[id].endEpoch;
    }

    function setEndEpoch(uint256 id, uint40 _endEpoch) external onlyContracts {
        knowledgeAssets[id].endEpoch = _endEpoch;

        emit KnowledgeAssetEndEpochUpdated(id, _endEpoch);
    }

    /// @notice DEPRECATED under OT-RFC-43 Option 1 (variant 1a). KA ids are
    ///         packed (author<<96)|number values, not globally sequential, so a
    ///         single "latest id" is meaningless. Always reverts — enumerate
    ///         KAs via the `KnowledgeAssetCreated` event (or per-CG lists).
    function getLatestKnowledgeAssetId() external pure returns (uint256) {
        revert GetLatestKnowledgeAssetIdDeprecated();
    }

    function currentTotalSupply() external view returns (uint256) {
        return _totalMintedKnowledgeAssetsCounter - _totalBurnedKnowledgeAssetsCounter;
    }

    function totalMinted() external view returns (uint256) {
        return _totalMintedKnowledgeAssetsCounter;
    }

    function totalBurned() external view returns (uint256) {
        return _totalBurnedKnowledgeAssetsCounter;
    }

    function getTotalTokenAmount() external view returns (uint96) {
        return _totalTokenAmount;
    }

    function isPartOfKnowledgeAsset(uint256 id, uint256 tokenId) external view returns (bool) {
        return id == tokenId && _ownerOf(tokenId) != address(0);
    }

    function getKnowledgeAssetId(uint256 tokenId) external view returns (uint256) {
        if (_ownerOf(tokenId) == address(0)) {
            return 0;
        }
        return tokenId;
    }

    function getKnowledgeAssetsRange(uint256 id) external view returns (uint256, uint256, uint256[] memory) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        if (ka.minted == 0) {
            return (0, 0, ka.burned);
        }
        return (id, id, ka.burned);
    }

    function getKnowledgeAssetsAmount(uint256 id) external view returns (uint256) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        return ka.minted - ka.burned.length;
    }

    function isKnowledgeAssetOwner(address owner, uint256 id) external view returns (bool) {
        return ownerOf(id) == owner;
    }

    function setURI(string memory baseURI) external onlyHub {
        _tokenURI = baseURI;
        emit URIUpdate(baseURI);
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        return _tokenURI;
    }

    function _safeGetLatestMerkleRootObject(
        uint256 id
    ) internal view returns (KnowledgeAssetLib.MerkleRoot memory) {
        KnowledgeAssetLib.KnowledgeAsset memory ka = knowledgeAssets[id];
        if (ka.merkleRoots.length == 0) {
            return KnowledgeAssetLib.MerkleRoot(address(0), bytes32(0), 0);
        }
        return ka.merkleRoots[ka.merkleRoots.length - 1];
    }

}
","keccak256":"0xcb37864ccc1d0a8e861de2c7b4152c808b3e4b8b2554a30a162e113ff03df048","license":"Apache-2.0"},"contracts/storage/EpochStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {Chronos} from "./Chronos.sol";
import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

contract EpochStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "EpochStorage";
    // 10.0.4 — OT-RFC-51 "Publishing Allocation": the per-node
    //          produced-knowledge-value accounting is repurposed as
    //          committed PCA "publishing allocation". The mappings,
    //          mutator, event, and getters are renamed
    //          (`*ProducedKnowledgeValue*` -> `*PublishingAllocation*`)
    //          and a net-zero `moveEpochPublishingAllocation` mutator is
    //          added so a PCA can re-designate its primary node without
    //          changing the epoch total (K_total).
    string private constant _VERSION = "10.0.4";

    event EpochPublishingAllocationAdded(uint72 indexed identityId, uint256 indexed epoch, uint96 amount);
    event TokensAddedToEpochRange(
        uint256 indexed shardId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint96 tokenAmount,
        uint96 remainder
    );
    event EpochTokensPaidOut(uint256 indexed shardId, uint256 indexed epoch, uint72 indexed identityId, uint96 amount);
    event EpochsFinalized(uint256 indexed shardId, uint256 startEpoch, uint256 endEpoch);

    Chronos public chronos;

    mapping(uint256 => uint256) public lastFinalizedEpoch;
    mapping(uint256 => uint96) public accumulatedRemainder;

    mapping(uint256 => mapping(uint256 => int96)) public diff;
    mapping(uint256 => mapping(uint256 => uint96)) public cumulative;
    mapping(uint256 => mapping(uint256 => uint96)) public distributed;

    mapping(uint72 => mapping(uint256 => uint96)) public nodesEpochPublishingAllocation;
    mapping(uint256 => uint96) public epochPublishingAllocation;
    mapping(uint256 => uint96) public epochNodeMaxPublishingAllocation;

    mapping(uint72 => mapping(uint256 => mapping(uint256 => uint96))) public nodesPaidOut;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function initialize() public onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function addEpochPublishingAllocation(
        uint72 identityId,
        uint256 epoch,
        uint96 amount
    ) external onlyContracts {
        nodesEpochPublishingAllocation[identityId][epoch] += amount;
        epochPublishingAllocation[epoch] += amount;

        // Maintain the per-epoch node max so its (public) getters stay
        // consistent. The OT-RFC-51 scoring path does NOT read it
        // (RandomSampling reads only getNodeEpochPublishingAllocation /
        // getEpochPublishingAllocation), but the mapping cannot be removed —
        // it precedes `nodesPaidOut` in this persistent (non-fresh-state)
        // storage layout — and leaving it written-nowhere/read-in-getters
        // trips Slither's uninitialized-state finding. The compare/SSTORE is
        // negligible against the surrounding accounting.
        if (nodesEpochPublishingAllocation[identityId][epoch] > epochNodeMaxPublishingAllocation[epoch]) {
            epochNodeMaxPublishingAllocation[epoch] = nodesEpochPublishingAllocation[identityId][epoch];
        }

        emit EpochPublishingAllocationAdded(identityId, epoch, amount);
    }

    /// @notice OT-RFC-51: move `amount` of publishing allocation from one
    ///         node to another within a single `epoch`. Used when a PCA
    ///         re-designates its primary node — the epoch total
    ///         (`epochPublishingAllocation`, i.e. K_total) is intentionally
    ///         NOT touched, so the move is net-zero on the denominator of
    ///         every node's publishing factor.
    /// @dev    `epochNodeMaxPublishingAllocation` is a per-epoch HIGH-WATER
    ///         MARK, maintained identically on the add and move paths: it is
    ///         only ever RAISED (when the destination's new value exceeds it),
    ///         never lowered by the `fromId` decrement — computing the true
    ///         current max after a decrement would need an O(nodes) scan.
    ///         Nothing on-chain reads it (scoring reads only
    ///         get(Node)EpochPublishingAllocation); it exists for off-chain
    ///         observability, for which the high-water-mark semantic is correct.
    function moveEpochPublishingAllocation(
        uint72 fromId,
        uint72 toId,
        uint256 epoch,
        uint96 amount
    ) external onlyContracts {
        nodesEpochPublishingAllocation[fromId][epoch] -= amount;
        nodesEpochPublishingAllocation[toId][epoch] += amount; // epoch total unchanged -> K_total net-zero

        if (nodesEpochPublishingAllocation[toId][epoch] > epochNodeMaxPublishingAllocation[epoch]) {
            epochNodeMaxPublishingAllocation[epoch] = nodesEpochPublishingAllocation[toId][epoch];
        }
    }

    function getEpochPublishingAllocation(uint256 epoch) external view returns (uint96) {
        return epochPublishingAllocation[epoch];
    }

    function getCurrentEpochPublishingAllocation() external view returns (uint96) {
        return epochPublishingAllocation[chronos.getCurrentEpoch()];
    }

    function getPreviousEpochPublishingAllocation() external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return epochPublishingAllocation[currentEpoch - 1];
    }

    function getNodeEpochPublishingAllocation(uint72 identityId, uint256 epoch) external view returns (uint96) {
        return nodesEpochPublishingAllocation[identityId][epoch];
    }

    function getNodeCurrentEpochPublishingAllocation(uint72 identityId) external view returns (uint96) {
        return nodesEpochPublishingAllocation[identityId][chronos.getCurrentEpoch()];
    }

    function getNodePreviousEpochPublishingAllocation(uint72 identityId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return nodesEpochPublishingAllocation[identityId][currentEpoch - 1];
    }

    function getEpochNodeMaxPublishingAllocation(uint256 epoch) external view returns (uint96) {
        return epochNodeMaxPublishingAllocation[epoch];
    }

    function getCurrentEpochNodeMaxPublishingAllocation() external view returns (uint96) {
        return epochNodeMaxPublishingAllocation[chronos.getCurrentEpoch()];
    }

    function getPreviousEpochNodeMaxPublishingAllocation() external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return epochNodeMaxPublishingAllocation[currentEpoch - 1];
    }

    function getNodeEpochPublishingAllocationPercentage(
        uint72 identityId,
        uint256 epoch
    ) external view returns (uint256) {
        if (epochPublishingAllocation[epoch] == 0) {
            return 0;
        }

        return
            (uint256(nodesEpochPublishingAllocation[identityId][epoch]) * 1e18) / epochPublishingAllocation[epoch];
    }

    function getNodeCurrentEpochPublishingAllocationPercentage(uint72 identityId) external view returns (uint256) {
        uint256 currentEpoch = chronos.getCurrentEpoch();

        if (epochPublishingAllocation[currentEpoch] == 0) {
            return 0;
        }

        return ((uint256(nodesEpochPublishingAllocation[identityId][currentEpoch]) * 1e18) /
            epochPublishingAllocation[currentEpoch]);
    }

    function getNodePreviousEpochPublishingAllocationPercentage(uint72 identityId) external view returns (uint256) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1 || epochPublishingAllocation[currentEpoch - 1] == 0) {
            return 0;
        }
        return ((uint256(nodesEpochPublishingAllocation[identityId][currentEpoch - 1]) * 1e18) /
            epochPublishingAllocation[currentEpoch - 1]);
    }

    function addTokensToEpochRange(
        uint256 shardId,
        uint256 startEpoch,
        uint256 endEpoch,
        uint96 tokenAmount
    ) external onlyContracts {
        // SECURITY FIX: a credit whose startEpoch is already FINALIZED is
        // otherwise lost forever. `_finalizeEpochsUpTo` only folds `diff` for
        // `(lastFinalizedEpoch, currentEpoch-1]` and never revisits a finalized
        // epoch, so `diff[startEpoch] += p` at `startEpoch <= lastFinalizedEpoch`
        // is never folded into `cumulative` (the tokens vanish — stranded in the
        // contract with no payable pool entry) and the paired
        // `diff[endEpoch+1] -= p` later under-credits an unrelated future epoch.
        //
        // Clamp the range up to `lastFinalizedEpoch + 1` — the first epoch NOT
        // yet folded into `cumulative`, and therefore still payable (epochs above
        // `lastFinalizedEpoch` are read via on-the-fly simulation in
        // `getEpochPool`). This is the minimal correction: it rescues only the
        // credits that were genuinely lost (finalized epochs) and lands them in
        // the CLOSEST still-creditable epoch, preserving the caller's intended
        // attribution as much as possible — PublishingConviction deliberately
        // attributes a closed billing window to the chain epochs it overlapped,
        // so forcing `currentEpoch` here would misattribute/delay those rewards
        // on an idle shard. Any stricter "settle into the current epoch" policy
        // belongs at the specific caller, not in this shared primitive. Clamp,
        // don't revert: lazy past-window settlement is an intended pattern.
        uint256 firstOpenEpoch = lastFinalizedEpoch[shardId] + 1;
        if (startEpoch < firstOpenEpoch) {
            startEpoch = firstOpenEpoch;
            if (endEpoch < startEpoch) {
                endEpoch = startEpoch;
            }
        }

        uint256 numEpochs = endEpoch - startEpoch + 1;

        uint96 totalTokens = tokenAmount + accumulatedRemainder[shardId];
        uint96 tokensPerEpochU = uint96(totalTokens / numEpochs);
        uint96 remainder = uint96(totalTokens % numEpochs);

        accumulatedRemainder[shardId] = remainder;

        int96 tokensPerEpoch = int96(tokensPerEpochU);

        diff[shardId][startEpoch] += tokensPerEpoch;
        diff[shardId][endEpoch + 1] -= tokensPerEpoch;

        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch > 1) {
            _finalizeEpochsUpTo(shardId, currentEpoch - 1);
        }

        emit TokensAddedToEpochRange(shardId, startEpoch, endEpoch, tokenAmount, remainder);
    }

    function payOutEpochTokens(
        uint256 shardId,
        uint256 epoch,
        uint72 identityId,
        uint96 amount
    ) external onlyContracts {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch > 1) {
            _finalizeEpochsUpTo(shardId, currentEpoch - 1);
        }

        distributed[shardId][epoch] += amount;
        nodesPaidOut[identityId][shardId][epoch] += amount;

        emit EpochTokensPaidOut(shardId, epoch, identityId, amount);
    }

    function getEpochPool(uint256 shardId, uint256 epoch) public view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch];
        } else {
            return _simulateEpochFinalization(shardId, epoch);
        }
    }

    function getEpochRemainingPool(uint256 shardId, uint256 epoch) public view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch] - distributed[shardId][epoch];
        } else {
            return _simulateEpochFinalization(shardId, epoch) - distributed[shardId][epoch];
        }
    }

    function getCurrentEpochPool(uint256 shardId) external view returns (uint96) {
        return getEpochPool(shardId, chronos.getCurrentEpoch());
    }

    function getCurrentEpochRemainingPool(uint256 shardId) external view returns (uint96) {
        return getEpochRemainingPool(shardId, chronos.getCurrentEpoch());
    }

    function getPreviousEpochPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return getEpochPool(shardId, currentEpoch - 1);
    }

    function getPreviousEpochRemainingPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return getEpochRemainingPool(shardId, currentEpoch - 1);
    }

    function getEpochRangePool(uint256 shardId, uint256 startEpoch, uint256 endEpoch) external view returns (uint96) {
        uint256 lastFinalized = lastFinalizedEpoch[shardId];
        uint96 totalPool = 0;

        if (startEpoch <= lastFinalized) {
            for (uint256 epoch = startEpoch; epoch <= lastFinalized && epoch <= endEpoch; epoch++) {
                totalPool += cumulative[shardId][epoch];
            }
        }

        uint96 simulatedCumulative = lastFinalized > 0 ? cumulative[shardId][lastFinalized] : cumulative[shardId][1];
        for (uint256 epoch = lastFinalized + 1; epoch <= endEpoch; epoch++) {
            int96 tmp = int96(simulatedCumulative) + diff[shardId][epoch];
            simulatedCumulative = uint96(tmp);
            if (epoch >= startEpoch) {
                totalPool += simulatedCumulative;
            }
        }

        return totalPool;
    }

    function getEpochDistributedPool(uint256 shardId, uint256 epoch) external view returns (uint96) {
        return distributed[shardId][epoch];
    }

    function getPreviousEpochDistributedPool(uint256 shardId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return distributed[shardId][currentEpoch - 1];
    }

    function getNodeEpochPaidOut(uint256 shardId, uint72 identityId, uint256 epoch) external view returns (uint96) {
        return nodesPaidOut[identityId][shardId][epoch];
    }

    function getNodePreviousEpochPaidOut(uint256 shardId, uint72 identityId) external view returns (uint96) {
        uint256 currentEpoch = chronos.getCurrentEpoch();
        if (currentEpoch <= 1) {
            return 0;
        }
        return nodesPaidOut[identityId][shardId][currentEpoch - 1];
    }

    function _finalizeEpochsUpTo(uint256 shardId, uint256 epoch) internal {
        uint256 startEpoch = lastFinalizedEpoch[shardId] + 1;
        for (uint256 e = startEpoch; e <= epoch; e++) {
            int96 prev = 0;
            if (e > 1) {
                prev = int96(cumulative[shardId][e - 1]);
            }
            cumulative[shardId][e] = uint96(prev + diff[shardId][e]);
        }
        lastFinalizedEpoch[shardId] = epoch;

        emit EpochsFinalized(shardId, startEpoch, epoch);
    }

    function _simulateEpochFinalization(uint256 shardId, uint256 epoch) internal view returns (uint96) {
        if (epoch <= lastFinalizedEpoch[shardId]) {
            return cumulative[shardId][epoch];
        }

        uint96 simulatedCumulative = 0;
        if (lastFinalizedEpoch[shardId] > 0) {
            simulatedCumulative = cumulative[shardId][lastFinalizedEpoch[shardId]];
        }

        for (uint256 e = lastFinalizedEpoch[shardId] + 1; e <= epoch; e++) {
            int96 prev = int96(simulatedCumulative);
            int96 result = prev + diff[shardId][e];
            simulatedCumulative = uint96(result);
        }

        return simulatedCumulative;
    }
}
","keccak256":"0x74fd4c074d1dbe46453f8ffb5ed1cf3db3ca100604d631b46f5be40860bd0835","license":"Apache-2.0"},"contracts/storage/Hub.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {IContractStatus} from "../interfaces/IContractStatus.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {HubLib} from "../libraries/HubLib.sol";
import {UnorderedNamedContractDynamicSet} from "../libraries/UnorderedNamedContractDynamicSet.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

contract Hub is INamed, IVersioned, Ownable {
    using UnorderedNamedContractDynamicSet for UnorderedNamedContractDynamicSet.Set;

    event NewContract(string contractName, address newContractAddress);
    event ContractChanged(string contractName, address newContractAddress);
    event NewAssetStorage(string contractName, address newContractAddress);
    event AssetStorageChanged(string contractName, address newContractAddress);
    event ContractRemoved(string contractName, address contractAddress);
    event AssetStorageRemoved(string contractName, address contractAddress);

    string private constant _NAME = "Hub";
    string private constant _VERSION = "1.0.0";

    UnorderedNamedContractDynamicSet.Set internal contractSet;
    UnorderedNamedContractDynamicSet.Set internal assetStorageSet;

    constructor() Ownable(msg.sender) {}

    // @dev Only transactions by HubController owner or one of the owners of the MultiSig Wallet
    modifier onlyOwnerOrMultiSigOwner() {
        _checkOwnerOrMultiSigOwner();
        _;
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function setContractAddress(
        string calldata contractName,
        address newContractAddress
    ) external onlyOwnerOrMultiSigOwner {
        _setContractAddress(contractName, newContractAddress);
    }

    function setAssetStorageAddress(string calldata assetStorageName, address assetStorageAddress) external onlyOwner {
        _setAssetStorageAddress(assetStorageName, assetStorageAddress);
    }

    function removeContractByName(string calldata contractName) external onlyOwner {
        if (contractSet.exists(contractName)) {
            address contractAddress = contractSet.get(contractName).addr;

            contractSet.remove(contractName);

            emit ContractRemoved(contractName, contractAddress);
        }
    }

    function removeContractByAddress(address contractAddress) external onlyOwner {
        if (contractSet.exists(contractAddress)) {
            string memory contractName = contractSet.get(contractAddress).name;

            contractSet.remove(contractAddress);

            emit ContractRemoved(contractName, contractAddress);
        }
    }

    function removeAssetStorageByName(string calldata assetStorageName) external onlyOwner {
        if (assetStorageSet.exists(assetStorageName)) {
            address assetStorageAddress = assetStorageSet.get(assetStorageName).addr;

            assetStorageSet.remove(assetStorageName);

            emit AssetStorageRemoved(assetStorageName, assetStorageAddress);
        }
    }

    function removeAssetStorageByAddress(address assetStorageAddress) external onlyOwner {
        if (assetStorageSet.exists(assetStorageAddress)) {
            string memory assetStorageName = assetStorageSet.get(assetStorageAddress).name;

            assetStorageSet.remove(assetStorageAddress);

            emit AssetStorageRemoved(assetStorageName, assetStorageAddress);
        }
    }

    function getContractAddress(string calldata contractName) external view returns (address) {
        return contractSet.get(contractName).addr;
    }

    function getAssetStorageAddress(string calldata assetStorageName) external view returns (address) {
        return assetStorageSet.get(assetStorageName).addr;
    }

    function getAllContracts() external view returns (UnorderedNamedContractDynamicSet.Contract[] memory) {
        return contractSet.getAll();
    }

    function getAllAssetStorages() external view returns (UnorderedNamedContractDynamicSet.Contract[] memory) {
        return assetStorageSet.getAll();
    }

    function isContract(string calldata contractName) external view returns (bool) {
        return contractSet.exists(contractName);
    }

    function isContract(address selectedContractAddress) external view returns (bool) {
        return contractSet.exists(selectedContractAddress);
    }

    function isAssetStorage(string calldata assetStorageName) external view returns (bool) {
        return assetStorageSet.exists(assetStorageName);
    }

    function isAssetStorage(address assetStorageAddress) external view returns (bool) {
        return assetStorageSet.exists(assetStorageAddress);
    }

    /**
     * @dev Forwards a function call to a specified target contract.
     * @notice This function can only be called by the contract owner or a multisig owner.
     * @param target The address of the target contract.
     * @param data The calldata containing the function signature and arguments for the target contract's function.
     * @return result The return data of the target contract's function call.
     */
    function forwardCall(address target, bytes calldata data) public onlyOwnerOrMultiSigOwner returns (bytes memory) {
        // Check if the target contract is registered in the Hub
        if (!contractSet.exists(target) && !assetStorageSet.exists(target)) {
            revert HubLib.InvalidTargetContract(target);
        }

        // Perform the function call to the target contract with the specified calldata
        (bool success, bytes memory result) = target.call{value: 0}(data);

        // If the call is unsuccessful, revert the transaction with the original revert reason
        if (!success) {
            assembly {
                // Load the free memory pointer from memory slot 0x40
                // Memory slot 0x40 is conventionally used to store the free memory pointer in Solidity, which points
                // to the next available memory slot for storing data during the execution of a contract function.
                let ptr := mload(0x40)
                // Get the size of the return data from the unsuccessful call
                let size := returndatasize()
                // Copy the return data to the memory location pointed to by ptr
                returndatacopy(ptr, 0, size)
                // Revert the transaction with the return data as the revert reason
                revert(ptr, size)
            }
        }

        return result;
    }

    function setAndReinitializeContracts(
        HubLib.Contract[] calldata newContracts,
        HubLib.Contract[] calldata newAssetStorageContracts,
        address[] calldata contractsToReinitialize,
        HubLib.ForwardCallInputArgs[] calldata forwardCallsData
    ) external onlyOwnerOrMultiSigOwner {
        _setContracts(newContracts);
        _setAssetStorageContracts(newAssetStorageContracts);
        _reinitializeContracts(contractsToReinitialize);
        _forwardCalls(forwardCallsData);
    }

    function _setContractAddress(string calldata contractName, address newContractAddress) internal {
        if (contractSet.exists(contractName)) {
            contractSet.update(contractName, newContractAddress);

            address oldContractAddress = contractSet.get(contractName).addr;
            if (_isContract(oldContractAddress)) {
                try IContractStatus(oldContractAddress).setStatus(false) {
                    // success
                } catch {
                    // Best-effort: contract may not implement IContractStatus; ignore.
                }
            }

            emit ContractChanged(contractName, newContractAddress);
        } else {
            contractSet.append(contractName, newContractAddress);

            emit NewContract(contractName, newContractAddress);
        }

        if (_isContract(newContractAddress)) {
            try IContractStatus(newContractAddress).setStatus(true) {
                // success
            } catch {
                // Best-effort: contract may not implement IContractStatus; ignore.
            }
        }

        emit NewContract(contractName, newContractAddress);
    }

    function _setContracts(HubLib.Contract[] calldata newContracts) internal {
        for (uint256 i; i < newContracts.length; ) {
            _setContractAddress(newContracts[i].name, newContracts[i].addr);

            unchecked {
                i++;
            }
        }
    }

    function _setAssetStorageAddress(string calldata assetStorageName, address assetStorageAddress) internal {
        if (assetStorageSet.exists(assetStorageName)) {
            emit AssetStorageChanged(assetStorageName, assetStorageAddress);
            assetStorageSet.update(assetStorageName, assetStorageAddress);
        } else {
            emit NewAssetStorage(assetStorageName, assetStorageAddress);
            assetStorageSet.append(assetStorageName, assetStorageAddress);
        }
    }

    function _setAssetStorageContracts(HubLib.Contract[] calldata newAssetStorageContracts) internal {
        for (uint256 i; i < newAssetStorageContracts.length; ) {
            _setAssetStorageAddress(newAssetStorageContracts[i].name, newAssetStorageContracts[i].addr);

            unchecked {
                i++;
            }
        }
    }

    function _reinitializeContracts(address[] calldata contractsToReinitialize) internal {
        for (uint256 i; i < contractsToReinitialize.length; ) {
            IInitializable(contractsToReinitialize[i]).initialize();
            unchecked {
                i++;
            }
        }
    }

    function _forwardCalls(HubLib.ForwardCallInputArgs[] calldata forwardCallsData) internal {
        for (uint256 i; i < forwardCallsData.length; ) {
            address contractAddress;

            // Try to get the contract address using getContractAddress
            try this.getContractAddress(forwardCallsData[i].contractName) returns (address addr) {
                contractAddress = addr;
            } catch {
                // If getContractAddress fails, try getAssetStorageAddress
                try this.getAssetStorageAddress(forwardCallsData[i].contractName) returns (address addr) {
                    contractAddress = addr;
                } catch {
                    revert HubLib.ContractNotRegistered(forwardCallsData[i].contractName);
                }
            }
            for (uint256 j; j < forwardCallsData[i].encodedData.length; ) {
                forwardCall(contractAddress, forwardCallsData[i].encodedData[j]);
                unchecked {
                    j++;
                }
            }
            unchecked {
                i++;
            }
        }
    }

    function _isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(addr)
        }
        return size > 0;
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
    }
}
","keccak256":"0x732252bb857277a35ab314beef2dbaceb5f96ce2f6d3b83a224927e503609def","license":"Apache-2.0"},"contracts/storage/IdentityStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {IERC734Extended} from "../interfaces/IERC734Extended.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ByteArr} from "../libraries/ByteArr.sol";
import {IdentityLib} from "../libraries/IdentityLib.sol";
import {IdentityStorage} from "../storage/IdentityStorage.sol";

contract IdentityStorage is IERC734Extended, INamed, IVersioned, HubDependent {
    using ByteArr for bytes32[];

    string private constant _NAME = "IdentityStorage";
    string private constant _VERSION = "10.0.2";

    uint72 public lastIdentityId;

    struct Identity {
        mapping(bytes32 => Key) keys;
        mapping(uint256 => bytes32[]) keysByPurpose;
    }

    // operationalKey => identityId
    mapping(bytes32 => uint72) public identityIds;
    // identityId => Identity
    mapping(uint72 => Identity) internal identities;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function deleteIdentity(uint72 identityId) external virtual onlyContracts {
        bytes32[] memory operationalKeys = identities[identityId].keysByPurpose[IdentityLib.OPERATIONAL_KEY];
        uint256 operationalKeysNumber = operationalKeys.length;

        for (uint256 i; i < operationalKeysNumber; ) {
            delete identityIds[operationalKeys[i]];
            unchecked {
                i++;
            }
        }

        delete identities[identityId];
    }

    function addKey(
        uint72 identityId,
        bytes32 _key,
        uint256 _purpose,
        uint256 _type
    ) external virtual override onlyContracts {
        Identity storage identity = identities[identityId];
        identity.keys[_key].purpose = _purpose;
        identity.keys[_key].keyType = _type;
        identity.keys[_key].key = _key;
        identity.keysByPurpose[_purpose].push(_key);

        emit KeyAdded(identityId, _key, _purpose, _type);
    }

    function removeKey(uint72 identityId, bytes32 _key) external virtual override onlyContracts {
        IdentityStorage.Identity storage identity = identities[identityId];

        uint256 index;
        (index, ) = identity.keysByPurpose[identity.keys[_key].purpose].indexOf(_key);
        identity.keysByPurpose[identity.keys[_key].purpose].removeByIndex(index);

        emit KeyRemoved(identityId, identity.keys[_key].key, identity.keys[_key].purpose, identity.keys[_key].keyType);

        delete identity.keys[_key];
    }

    function keyHasPurpose(
        uint72 identityId,
        bytes32 _key,
        uint256 _purpose
    ) external view virtual override returns (bool) {
        return identities[identityId].keys[_key].purpose == _purpose;
    }

    function getKey(
        uint72 identityId,
        bytes32 _key
    ) external view virtual override returns (uint256, uint256, bytes32) {
        return (
            identities[identityId].keys[_key].purpose,
            identities[identityId].keys[_key].keyType,
            identities[identityId].keys[_key].key
        );
    }

    function getKeysByPurpose(
        uint72 identityId,
        uint256 _purpose
    ) external view virtual override returns (bytes32[] memory) {
        return identities[identityId].keysByPurpose[_purpose];
    }

    function getIdentityId(address operational) external view returns (uint72) {
        return identityIds[keccak256(abi.encodePacked(operational))];
    }

    function setOperationalKeyIdentityId(bytes32 operationalKey, uint72 identityId) external virtual onlyContracts {
        identityIds[operationalKey] = identityId;
    }

    function removeOperationalKeyIdentityId(bytes32 operationalKey) external virtual onlyContracts {
        delete identityIds[operationalKey];
    }

    function setLastIdentityId(uint72 identityId) external virtual onlyContracts {
        lastIdentityId = identityId;
    }

    function generateIdentityId() external virtual onlyContracts returns (uint72) {
        unchecked {
            return ++lastIdentityId;
        }
    }
}
","keccak256":"0xef5c32eff475aef41483352683fad4e27f33e2bb9d4a0b891cf02e1987acce91","license":"Apache-2.0"},"contracts/storage/ParametersStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";

contract ParametersStorage is INamed, IVersioned, HubDependent {
    event ParameterChanged(string parameterName, uint256 parameterValue);
    /// @notice Emitted when the protocol treasury recipient changes. The
    ///         address is carried in its own event (rather than the
    ///         `uint256`-valued `ParameterChanged`) so off-chain indexers get a
    ///         typed `address` field.
    event ProtocolTreasurySet(address indexed treasury);

    error ZeroShardingTableSizeLimit();

    string private constant _NAME = "ParametersStorage";
    // protocol treasury fee (`protocolTreasuryFee`, `protocolTreasury`,
    // `MAX_PROTOCOL_TREASURY_FEE`) skimmed from the staker-bound TRAC on
    // every paid publish / update / lifetime-extension.
    string private constant _VERSION = "10.0.4";

    uint96 public minimumStake;
    uint96 public maximumStake;

    uint256 public stakeWithdrawalDelay;
    uint256 public nodeAskUpdateDelay;
    uint256 public operatorFeeUpdateDelay;

    uint16 public opWalletsLimitOnProfileCreation;
    uint16 public shardingTableSizeLimit;

    uint256 public minimumRequiredSignatures;

    uint256 public askUpperBoundFactor;
    uint256 public askLowerBoundFactor;

    uint16 public maxOperatorFee;

    uint256 public v81ReleaseEpoch;
    uint256 public publishingConvictionEpochs;

    /// @notice Protocol treasury fee in basis points (out of 10_000) skimmed
    ///         from the staker-bound TRAC on every paid publish / update /
    ///         lifetime-extension. The fee is taken out of the amount that
    ///         would otherwise flow to the staker reward pool — it does NOT
    ///         change the price a publisher pays. Default 300 (3%).
    ///
    ///         The fee is a no-op while `protocolTreasury == address(0)`
    ///         (the full amount flows to stakers), so it stays dormant until
    ///         governance wires a treasury recipient via `setProtocolTreasury`.
    uint16 public protocolTreasuryFee;

    /// @notice Recipient of the protocol treasury fee. The zero address
    ///         disables the fee entirely regardless of `protocolTreasuryFee`.
    address public protocolTreasury;

    /// @notice Minimum TRAC deposit required to register a Context Graph
    ///         on-chain (`ContextGraphs.createContextGraph`). The deposit is
    ///         held as the CG's prepaid publishing escrow — spendable by the
    ///         CG owner on publish/update/extend into that CG — and is never
    ///         cash-refundable (residue sweeps to the staker reward pool on
    ///         deactivation). Anti-spam for the unbounded-CG-creation DoS
    ///         (OT-RFC-53). Setting it to 0 disables the deposit (dormant).
    uint96 public contextGraphRegistrationDeposit;

    /// @notice Hard upper bound on `protocolTreasuryFee` (10%). Bounds
    ///         governance so the fee can never be set to an extractive level
    ///         that would starve the staker reward pool.
    uint16 public constant MAX_PROTOCOL_TREASURY_FEE = 1_000;

    /// @notice Hard upper bound on `publishingConvictionEpochs`.
    ///
    /// `DKGPublishingConvictionNFT._settleElapsed` / `_finalSweep` loop
    /// `lockDurationEpochs` times in the worst case (dormant account
    /// settled at expiry). Each iteration costs ~30–50k gas
    /// (`windowSpent` SLOAD + one or two `epochStorage.addTokensToEpochRange`
    /// writes + a `WindowSettled` event), so an unbounded
    /// `publishingConvictionEpochs` (the previous cap was `uint16.max`)
    /// would let governance brick PCAs by setting the parameter past
    /// the block-gas budget. 60 chain epochs ≈ 5 years at a 1-month
    /// epoch length and worst-cases at ~3M gas — comfortably below
    /// the block limit while leaving room for the surrounding
    /// `publish` / `topUp` / NFT-transfer work.
    uint256 public constant MAX_PUBLISHING_CONVICTION_EPOCHS = 60;

    // @dev Only transactions by HubController owner or one of the owners of the MultiSig Wallet
    modifier onlyOwnerOrMultiSigOwner() {
        _checkOwnerOrMultiSigOwner();
        _;
    }

    constructor(address hubAddress, uint256 _v81ReleaseEpoch) HubDependent(hubAddress) {
        minimumStake = 50_000 ether;
        maximumStake = 10_000_000 ether;

        stakeWithdrawalDelay = 28 days;
        nodeAskUpdateDelay = 1 days;
        operatorFeeUpdateDelay = 28 days;

        opWalletsLimitOnProfileCreation = 50;
        shardingTableSizeLimit = 500;

        minimumRequiredSignatures = 3;

        askUpperBoundFactor = 1467000000000000000;
        askLowerBoundFactor = 533000000000000000;

        maxOperatorFee = 10_000;

        // Epoch when v8.1 was released on mainnet/testnet
        // Change if you ever redeploy delegatorsInfo contract on either network
        v81ReleaseEpoch = _v81ReleaseEpoch;
        publishingConvictionEpochs = 12;

        // 3% default. Dormant until `protocolTreasury` is set (defaults to
        // the zero address), so a fresh deploy behaves exactly as before
        // until governance opts in.
        protocolTreasuryFee = 300;

        // OT-RFC-53: constructor leaves the registration deposit at 0; the
        // standard deploy sets the live value (100 TRAC) via a post-deploy
        // script that calls `setContextGraphRegistrationDeposit`. This protects
        // production automatically (no manual step, no silent-off) while keeping
        // test fixtures — which don't run that script — unaffected. Governance
        // can retune or disable it anytime.
    }

    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    function setAskUpperBoundFactor(uint256 _askUpperBoundFactor) external onlyOwnerOrMultiSigOwner {
        askUpperBoundFactor = _askUpperBoundFactor;
    }

    function setAskLowerBoundFactor(uint256 _askLowerBoundFactor) external onlyOwnerOrMultiSigOwner {
        askLowerBoundFactor = _askLowerBoundFactor;
    }

    function setMinimumRequiredSignatures(uint256 _minimumRequiredSignatures) external onlyOwnerOrMultiSigOwner {
        minimumRequiredSignatures = _minimumRequiredSignatures;

        emit ParameterChanged("minimumRequiredSignatures", _minimumRequiredSignatures);
    }

    function setMinimumStake(uint96 newMinimumStake) external onlyOwnerOrMultiSigOwner {
        minimumStake = newMinimumStake;

        emit ParameterChanged("minimumStake", newMinimumStake);
    }

    function setMaximumStake(uint96 newMaximumStake) external onlyOwnerOrMultiSigOwner {
        maximumStake = newMaximumStake;

        emit ParameterChanged("maximumStake", newMaximumStake);
    }

    function setStakeWithdrawalDelay(uint256 newStakeWithdrawalDelay) external onlyOwnerOrMultiSigOwner {
        stakeWithdrawalDelay = newStakeWithdrawalDelay;

        emit ParameterChanged("stakeWithdrawalDelay", newStakeWithdrawalDelay);
    }

    function setNodeAskUpdateDelay(uint256 newNodeAskUpdateDelay) external onlyOwnerOrMultiSigOwner {
        nodeAskUpdateDelay = newNodeAskUpdateDelay;

        emit ParameterChanged("nodeAskUpdateDelay", newNodeAskUpdateDelay);
    }

    function setOperatorFeeUpdateDelay(uint256 newOperatorFeeUpdateDelay) external onlyOwnerOrMultiSigOwner {
        operatorFeeUpdateDelay = newOperatorFeeUpdateDelay;

        emit ParameterChanged("operatorFeeUpdateDelay", newOperatorFeeUpdateDelay);
    }

    function setOpWalletsLimitOnProfileCreation(
        uint16 opWalletsLimitOnProfileCreation_
    ) external onlyOwnerOrMultiSigOwner {
        opWalletsLimitOnProfileCreation = opWalletsLimitOnProfileCreation_;

        emit ParameterChanged("opWalletsLimitOnProfileCreation", opWalletsLimitOnProfileCreation);
    }

    function setShardingTableSizeLimit(uint16 shardingTableSizeLimit_) external onlyOwnerOrMultiSigOwner {
        // Reject 0: ShardingTable._insertNode now enforces this cap
        // (`nodesCount >= limit` reverts ShardingTableIsFull), so a 0 limit would
        // freeze ALL node admission (even the first insert), bricking staking. 0
        // is never a meaningful table size — reject it rather than let it act as
        // an implicit pause switch.
        if (shardingTableSizeLimit_ == 0) revert ZeroShardingTableSizeLimit();
        shardingTableSizeLimit = shardingTableSizeLimit_;

        emit ParameterChanged("shardingTableSizeLimit", shardingTableSizeLimit);
    }

    function setMaxOperatorFee(uint16 maxOperatorFee_) external onlyOwnerOrMultiSigOwner {
        maxOperatorFee = maxOperatorFee_;

        emit ParameterChanged("maxOperatorFee", maxOperatorFee);
    }

    function setV81ReleaseEpoch(uint256 _v81ReleaseEpoch) external onlyOwnerOrMultiSigOwner {
        v81ReleaseEpoch = _v81ReleaseEpoch;

        emit ParameterChanged("v81ReleaseEpoch", _v81ReleaseEpoch);
    }

    function setPublishingConvictionEpochs(
        uint256 _publishingConvictionEpochs
    ) external onlyOwnerOrMultiSigOwner {
        require(_publishingConvictionEpochs > 0, "publishingConvictionEpochs must be > 0");
        // See `MAX_PUBLISHING_CONVICTION_EPOCHS` for the gas-budget
        // rationale. The previous `<= type(uint16).max` bound permitted
        // values that would gas-out PCA settlement.
        require(
            _publishingConvictionEpochs <= MAX_PUBLISHING_CONVICTION_EPOCHS,
            "publishingConvictionEpochs too large"
        );
        publishingConvictionEpochs = _publishingConvictionEpochs;

        emit ParameterChanged("publishingConvictionEpochs", _publishingConvictionEpochs);
    }

    function setContextGraphRegistrationDeposit(uint96 amount) external onlyOwnerOrMultiSigOwner {
        contextGraphRegistrationDeposit = amount;

        emit ParameterChanged("contextGraphRegistrationDeposit", amount);
    }

    function setProtocolTreasuryFee(uint16 protocolTreasuryFee_) external onlyOwnerOrMultiSigOwner {
        // See `MAX_PROTOCOL_TREASURY_FEE` for the rationale on the upper
        // bound. 0 is allowed (disables the fee while keeping the recipient
        // wired) — the floor is enforced implicitly by the unsigned type.
        require(protocolTreasuryFee_ <= MAX_PROTOCOL_TREASURY_FEE, "protocolTreasuryFee too large");
        protocolTreasuryFee = protocolTreasuryFee_;

        emit ParameterChanged("protocolTreasuryFee", protocolTreasuryFee_);
    }

    function setProtocolTreasury(address protocolTreasury_) external onlyOwnerOrMultiSigOwner {
        protocolTreasury = protocolTreasury_;

        emit ProtocolTreasurySet(protocolTreasury_);
    }

    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        // First check if the address has contract code
        uint256 size;
        assembly {
            size := extcodesize(multiSigAddress)
        }

        // If no contract code, it's an EOA, not a multisig
        if (size == 0) {
            return false;
        }

        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && msg.sender != address(hub) && !_isMultiSigOwner(hubOwner)) {
            revert("Only Hub Owner, Hub, or Multisig Owner can call");
        }
    }
}
","keccak256":"0xcfa8ee19dacc2be0de28973802d18037bfac66537db226afc21d259611c5bac2","license":"Apache-2.0"},"contracts/storage/ProfileStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {HubDependent} from "../abstract/HubDependent.sol";
import {ProfileLib} from "../libraries/ProfileLib.sol";
import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";

contract ProfileStorage is INamed, IVersioned, HubDependent {
    string private constant _NAME = "ProfileStorage";
    // Bumped 1.0.0 -> 1.1.0: ProfileInfo struct extended with relayCapable
    // (RFC 04 v0.3 / Issue #461). New mapping reads on existing keys return
    // false for the new field. Multiaddrs were briefly added on a prior
    // revision but are deliberately not stored on Profile (RFC 04 §5.2).
    // 10.0.3 -> 10.0.4: active-fee getters (fee / percentage / effective-date)
    // centralized in `_activeOperatorFee`, fixing the `operatorFees[length - 2]`
    // underflow panic on the single-not-yet-effective-fee state (the effective-date
    // getter still had it).
    string private constant _VERSION = "10.0.4";

    event ProfileCreated(uint72 indexed identityId, string nodeName, bytes nodeId, uint16 initialOperatorFee);
    event ProfileDeleted(uint72 indexed identityId, bytes nodeId);
    event NodeNameUpdated(uint72 indexed identityId, string oldName, string newName);
    event NodeIdUpdated(uint72 indexed identityId, bytes oldNodeId, bytes newNodeId);
    event NodeAskUpdated(uint72 indexed identityId, uint96 oldAsk, uint96 newAsk);
    event OperatorFeeAdded(uint72 indexed identityId, uint16 feePercentage, uint256 effectiveDate);
    event OperatorFeesReplaced(
        uint72 indexed identityId,
        uint16 oldFeePercentage,
        uint16 newFeePercentage,
        uint256 effectiveDate
    );
    event OperatorFeesUpdated(uint72 indexed identityId, ProfileLib.OperatorFee[] operatorFees);
    // RFC 04 v0.3: relay-capability flag (multiaddrs live in attestation KAs, not Profile).
    event RelayCapabilityUpdated(uint72 indexed identityId, bool oldValue, bool newValue);

    mapping(uint72 => ProfileLib.ProfileInfo) public profiles;
    mapping(string => bool) public isNameTaken;
    mapping(bytes => bool) public nodeIdsList;
    mapping(uint72 => uint256) public askUpdateCooldown;

    constructor(address hubAddress) HubDependent(hubAddress) {}

    function name() external pure override returns (string memory) {
        return _NAME;
    }

    function version() external pure override returns (string memory) {
        return _VERSION;
    }

    function createProfile(
        uint72 identityId,
        string calldata nodeName,
        bytes calldata nodeId,
        uint16 initialOperatorFee
    ) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        profile.name = nodeName;
        profile.nodeId = nodeId;
        profile.operatorFees.push(ProfileLib.OperatorFee(initialOperatorFee, block.timestamp));
        nodeIdsList[nodeId] = true;

        emit ProfileCreated(identityId, nodeName, nodeId, initialOperatorFee);
    }

    function getProfile(
        uint72 identityId
    )
        external
        view
        returns (
            string memory,
            bytes memory,
            uint96,
            ProfileLib.OperatorFee[] memory,
            bool
        )
    {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];

        return (
            profile.name,
            profile.nodeId,
            profile.ask,
            profile.operatorFees,
            profile.relayCapable
        );
    }

    function deleteProfile(uint72 identityId) external onlyContracts {
        bytes memory nodeId = profiles[identityId].nodeId;
        nodeIdsList[nodeId] = false;
        delete profiles[identityId];

        emit ProfileDeleted(identityId, nodeId);
    }

    function getName(uint72 identityId) external view returns (string memory) {
        return profiles[identityId].name;
    }

    function setName(uint72 identityId, string memory _name) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        string memory oldName = profile.name;

        profile.name = _name;

        emit NodeNameUpdated(identityId, oldName, _name);
    }

    function getNodeId(uint72 identityId) external view returns (bytes memory) {
        return profiles[identityId].nodeId;
    }

    function setNodeId(uint72 identityId, bytes calldata nodeId) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        bytes memory oldNodeId = profile.nodeId;

        nodeIdsList[oldNodeId] = false;
        profile.nodeId = nodeId;
        nodeIdsList[nodeId] = true;

        emit NodeIdUpdated(identityId, oldNodeId, nodeId);
    }

    function setAsk(uint72 identityId, uint96 ask) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        uint96 oldAsk = profile.ask;

        profile.ask = ask;

        emit NodeAskUpdated(identityId, oldAsk, ask);
    }

    function setAskUpdateCooldown(uint72 identityId, uint256 cooldownEnd) external onlyContracts {
        askUpdateCooldown[identityId] = cooldownEnd;
    }

    function getAsk(uint72 identityId) external view returns (uint96) {
        return profiles[identityId].ask;
    }

    function addOperatorFee(uint72 identityId, uint16 feePercentage, uint256 effectiveDate) external onlyContracts {
        profiles[identityId].operatorFees.push(ProfileLib.OperatorFee(feePercentage, effectiveDate));

        emit OperatorFeeAdded(identityId, feePercentage, effectiveDate);
    }

    function getOperatorFee(uint72 identityId) external view returns (uint16) {
        return getActiveOperatorFeePercentage(identityId);
    }

    function getOperatorFees(uint72 identityId) external view returns (ProfileLib.OperatorFee[] memory) {
        return profiles[identityId].operatorFees;
    }

    function setOperatorFees(uint72 identityId, ProfileLib.OperatorFee[] memory operatorFees) external onlyContracts {
        profiles[identityId].operatorFees = operatorFees;

        emit OperatorFeesUpdated(identityId, operatorFees);
    }

    // =====================================================================
    // RFC 04 v0.3 / Issue #461 — relay-capability flag.
    //
    // This flag is the operator's "I intend to run as a relay" hint. It
    // gates the operator's per-round attestation publish (RFC 04 Phase 2)
    // — operators with relayCapable=false don't bother running the cosig
    // + submit pipeline at all. Multiaddrs themselves live in the
    // per-round attestation KA body, not on Profile (RFC 04 §5.2).
    // =====================================================================

    function getRelayCapable(uint72 identityId) external view returns (bool) {
        return profiles[identityId].relayCapable;
    }

    function setRelayCapable(uint72 identityId, bool relayCapable) external onlyContracts {
        ProfileLib.ProfileInfo storage profile = profiles[identityId];
        bool oldValue = profile.relayCapable;
        profile.relayCapable = relayCapable;

        emit RelayCapabilityUpdated(identityId, oldValue, relayCapable);
    }

    function replacePendingOperatorFee(
        uint72 identityId,
        uint16 feePercentage,
        uint256 effectiveDate
    ) external onlyContracts {
        if (
            profiles[identityId].operatorFees.length == 0 ||
            block.timestamp >
            profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1].effectiveDate
        ) {
            revert ProfileLib.NoPendingOperatorFee();
        }

        uint16 oldFeePercentage = profiles[identityId]
            .operatorFees[profiles[identityId].operatorFees.length - 1]
            .feePercentage;
        profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1] = ProfileLib.OperatorFee({
            feePercentage: feePercentage,
            effectiveDate: effectiveDate
        });

        emit OperatorFeesReplaced(identityId, oldFeePercentage, feePercentage, effectiveDate);
    }

    function getOperatorFeesLength(uint72 identityId) external view returns (uint256) {
        return profiles[identityId].operatorFees.length;
    }

    function getOperatorFeeByIndex(
        uint72 identityId,
        uint256 index
    ) public view returns (ProfileLib.OperatorFee memory) {
        return profiles[identityId].operatorFees[index];
    }

    function getOperatorFeeByTimestamp(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (ProfileLib.OperatorFee memory) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false);
    }

    function getOperatorFeeByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (ProfileLib.OperatorFee memory) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true);
    }

    function getLatestOperatorFee(uint72 identityId) external view returns (ProfileLib.OperatorFee memory) {
        return _safeGetLatestOperatorFee(identityId);
    }

    /// @dev The currently-active operator fee. Centralizes the `length - 2`
    ///      underflow guard so every active-fee getter (fee / percentage /
    ///      effective-date) shares ONE implementation. A single fee is always
    ///      active; with more than one, the latest applies once its effectiveDate
    ///      has passed (strict `>`), otherwise the prior fee. The `length == 1`
    ///      guard also covers the createProfile case where the initial fee's
    ///      effectiveDate == block.timestamp would otherwise hit `length - 2`.
    function _activeOperatorFee(uint72 identityId) internal view returns (ProfileLib.OperatorFee memory) {
        ProfileLib.OperatorFee[] storage fees = profiles[identityId].operatorFees;
        uint256 length = fees.length;
        if (length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        }
        if (length == 1 || block.timestamp > fees[length - 1].effectiveDate) {
            return fees[length - 1];
        }
        return fees[length - 2];
    }

    function getActiveOperatorFee(uint72 identityId) external view returns (ProfileLib.OperatorFee memory) {
        return _activeOperatorFee(identityId);
    }

    function getOperatorFeePercentageByIndex(uint72 identityId, uint256 index) external view returns (uint16) {
        return profiles[identityId].operatorFees[index].feePercentage;
    }

    function getOperatorFeePercentageByTimestamp(uint72 identityId, uint256 timestamp) external view returns (uint16) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false).feePercentage;
    }

    function getOperatorFeePercentageByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint16) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true).feePercentage;
    }

    function getLatestOperatorFeePercentage(uint72 identityId) external view returns (uint16) {
        return _safeGetLatestOperatorFee(identityId).feePercentage;
    }

    function getActiveOperatorFeePercentage(uint72 identityId) public view returns (uint16) {
        return _activeOperatorFee(identityId).feePercentage;
    }

    function getOperatorFeeEffectiveDateByIndex(uint72 identityId, uint256 index) external view returns (uint256) {
        return profiles[identityId].operatorFees[index].effectiveDate;
    }

    function getOperatorFeeEffectiveDateByTimestamp(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint256) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, false).effectiveDate;
    }

    function getOperatorFeeEffectiveDateByTimestampReverse(
        uint72 identityId,
        uint256 timestamp
    ) external view returns (uint256) {
        return _getOperatorFeeByTimestamp(identityId, timestamp, true).effectiveDate;
    }

    function getLatestOperatorFeeEffectiveDate(uint72 identityId) external view returns (uint256) {
        return _safeGetLatestOperatorFee(identityId).effectiveDate;
    }

    function getActiveOperatorFeeEffectiveDate(uint72 identityId) external view returns (uint256) {
        return _activeOperatorFee(identityId).effectiveDate;
    }

    function isOperatorFeeChangePending(uint72 identityId) external view returns (bool) {
        return (profiles[identityId].operatorFees.length != 0 &&
            block.timestamp <=
            profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1].effectiveDate);
    }

    function profileExists(uint72 identityId) external view returns (bool) {
        return keccak256(profiles[identityId].nodeId) != keccak256(bytes(""));
    }

    function _safeGetLatestOperatorFee(uint72 identityId) internal view returns (ProfileLib.OperatorFee memory) {
        if (profiles[identityId].operatorFees.length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        } else {
            return profiles[identityId].operatorFees[profiles[identityId].operatorFees.length - 1];
        }
    }

    function _getOperatorFeeByTimestamp(
        uint72 identityId,
        uint256 timestamp,
        bool reverseLookup
    ) internal view returns (ProfileLib.OperatorFee memory) {
        ProfileLib.OperatorFee[] storage fees = profiles[identityId].operatorFees;

        if (fees.length == 0) {
            return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
        }
        if (timestamp > fees[fees.length - 1].effectiveDate) {
            return fees[fees.length - 1];
        }
        if (timestamp < fees[0].effectiveDate) {
            return fees[0];
        }
        if (reverseLookup) {
            for (uint256 i = fees.length - 1; i > 0; ) {
                unchecked {
                    --i;
                }
                if (fees[i].effectiveDate <= timestamp) {
                    return fees[i];
                }
            }
            return fees[0];
        } else {
            for (uint256 i; i < fees.length; ) {
                if (fees[i].effectiveDate > timestamp) {
                    return i == 0 ? fees[0] : fees[i - 1];
                }
                unchecked {
                    ++i;
                }
            }
        }
        return ProfileLib.OperatorFee({feePercentage: 0, effectiveDate: 0});
    }
}
","keccak256":"0x68b24133d7ceccb0eeaa3633399790ee70e0a6036f554bab2edc90b1f1e01f1f","license":"Apache-2.0"},"contracts/storage/RandomSamplingStorage.sol":{"content":"// SPDX-License-Identifier: Apache-2.0

pragma solidity ^0.8.20;

import {INamed} from "../interfaces/INamed.sol";
import {IVersioned} from "../interfaces/IVersioned.sol";
import {IInitializable} from "../interfaces/IInitializable.sol";
import {RandomSamplingLib} from "../libraries/RandomSamplingLib.sol";
import {Chronos} from "../storage/Chronos.sol";
import {ContractStatus} from "../abstract/ContractStatus.sol";
import {ICustodian} from "../interfaces/ICustodian.sol";
import {HubLib} from "../libraries/HubLib.sol";

contract RandomSamplingStorage is INamed, IVersioned, IInitializable, ContractStatus {
    string private constant _NAME = "RandomSamplingStorage";
    // 1.0.0 — original scalar nodeEpochScorePerStake.
    // 2.0.0 — D26 C.2 shape: per-(identityId, epoch) EpochIndex with
    //         firstScorePerStake36 / lastScorePerStake36 sentinels plus a
    //         timestamped Checkpoint[] mid array appended by submitProof.
    //         Legacy `getNodeEpochScorePerStake` / `addToNodeEpochScorePerStake`
    //         / `setNodeEpochScorePerStake` preserved as adapters over the
    //         new structure. Scalar mapping removed.
    // 3.0.0 — D26 code-review follow-ups (M6/M7/L6):
    //         * `EpochIndex.firstScorePerStake36` removed. Under D26
    //           `scorePerStake36` is epoch-local (accumulates from 0 per
    //           epoch), so the sentinel was always 0 — one SSTORE slot
    //           reclaimed per epoch first-write.
    //         * `EpochIndex.firstInitialized` removed. It was set on first
    //           write and never read for correctness; `isEpochFirstInitialized`
    //           view is retired.
    //         * `setLastScorePerStake` removed — test-only path that
    //           could desynchronize `mid[tail]` from `lastScorePerStake36`
    //           and silently corrupt claim math. Tests now drive state
    //           through `appendCheckpoint`.
    //         * `getEpochFirstScorePerStake` retired (always 0 under D26).
    // 10.0.2 → 10.1.0: OT-RFC-49 — `RandomSamplingLib.Challenge` grew two
    // pinned fields (`challengeLeafCount`, `challengeRoot`) so the persisted
    // tuple via `getNodeChallenge`/`setNodeChallenge` is wider; the migration
    // `clearOutstandingChallenges` admin path is added in WS-E.
    // 10.2.0 — Audit G-3: new `nodeChallengeStakeSnapshot` mapping (+ a
    // `nodeChallengeStakeSnapshotSet` present-flag and setter) records the node's
    // effective stake at challenge creation so submitProof can score against
    // min(snapshot, live), defeating within-period flash-stake spikes. The flag
    // (not snapshot != 0) gates the cap so a zero-stake node is still capped at 0.
    string private constant _VERSION = "10.2.0";
    uint8 public constant CHUNK_BYTE_SIZE = 32;
    Chronos public chronos;

    uint256 public w1;
    uint256 public w2;

    RandomSamplingLib.ProofingPeriodDuration[] public proofingPeriodDurations;

    uint256 private activeProofPeriodStartBlock;
    // identityId => Challenge - used in proof to verify the challenge is within proofing period
    mapping(uint72 => RandomSamplingLib.Challenge) public nodesChallenges;
    // epoch => identityId => successful proofs count
    mapping(uint256 => mapping(uint72 => uint256)) public epochNodeValidProofsCount;
    // identityId => epoch => proofPeriodStartBlock => score
    mapping(uint72 => mapping(uint256 => mapping(uint256 => uint256))) public nodeEpochProofPeriodScore;
    // identityId => epoch => score
    mapping(uint72 => mapping(uint256 => uint256)) public nodeEpochScore;
    // epoch => score
    mapping(uint256 => uint256) public allNodesEpochScore;
    // epoch => identityId => delegatorKey => score
    mapping(uint256 => mapping(uint72 => mapping(bytes32 => uint256))) public epochNodeDelegatorScore;

    // ============================================================
    //     D26 — C.2 per-(identityId, epoch) score-per-stake index
    // ============================================================
    //
    // `lastScorePerStake36` is the epoch-end cumulative score-per-stake
    // (strictly monotonic across the epoch). `mid` is appended once per
    // proof (timestamped) so claim can binary-search for the scorePerStake
    // at an arbitrary `ts` in the epoch (used when a delegator's boost
    // expires mid-epoch).
    //
    // M6/M7 — the pre-3.0.0 layout carried a `firstScorePerStake36` +
    // `firstInitialized` pair. Under D26, scorePerStake36 is epoch-local
    // (accumulates from 0), so the "first" sentinel was always 0 and the
    // "initialized" flag was set but never consulted. Both fields are
    // removed; `findScorePerStakeAt` now returns 0 for timestamps before
    // the first checkpoint (the natural default).
    struct Checkpoint {
        uint40 timestamp;
        uint216 scorePerStake36;
    }
    struct EpochIndex {
        uint256 lastScorePerStake36;
        Checkpoint[] mid;
    }
    // identityId => epoch => EpochIndex
    mapping(uint72 => mapping(uint256 => EpochIndex)) internal nodeEpochIndex;

    // epoch => identityId => delegatorKey => last settled scorePerStake36
    //
    // (The legacy name is preserved; this value is now the delegator's
    // cursor into the new EpochIndex.lastScorePerStake36 stream.)
    mapping(uint256 => mapping(uint72 => mapping(bytes32 => uint256)))
        public delegatorLastSettledNodeEpochScorePerStake;

    // ── Audit G-3 (10.2.0) — APPENDED after all pre-existing state so no slot of
    //    the score/reward mappings above shifts (upgrade-safe layout).
    // identityId => node effective stake snapshotted at challenge creation.
    // submitProof scores against min(snapshot, live) so a within-period flash-stake
    // cannot inflate the (sticky, whole-epoch) score. A value of 0 here is a VALID
    // snapshot (a node with zero challenge-time stake is still capped at 0, not left
    // uncapped) — presence is tracked by the explicit flag below, never by the value.
    mapping(uint72 => uint256) public nodeChallengeStakeSnapshot;
    // identityId => whether the CURRENT challenge has a stake snapshot recorded.
    // Set by `setNodeChallengeStakeSnapshot` (only `createChallenge` calls it); an
    // injected challenge via the privileged `setNodeChallenge` path has no snapshot.
    mapping(uint72 => bool) public nodeChallengeStakeSnapshotSet;

    event W1Set(uint256 oldW1, uint256 newW1);
    event W2Set(uint256 oldW2, uint256 newW2);
    event ProofingPeriodDurationAdded(uint16 durationInBlocks, uint256 indexed effectiveEpoch);
    event PendingProofingPeriodDurationReplaced(
        uint16 oldDurationInBlocks,
        uint16 newDurationInBlocks,
        uint256 indexed effectiveEpoch
    );
    event NodeEpochScoreAdded(uint256 indexed epoch, uint72 indexed identityId, uint256 scoreAdded, uint256 totalScore);
    event AllNodesEpochScoreAdded(uint256 indexed epoch, uint256 scoreAdded, uint256 totalScore);
    event NodeEpochProofPeriodScoreAdded(
        uint256 indexed epoch,
        uint256 indexed proofPeriodStartBlock,
        uint72 indexed identityId,
        uint256 scoreAdded,
        uint256 totalScore
    );
    event NodeEpochProofPeriodScoreSet(
        uint256 indexed epoch,
        uint256 indexed proofPeriodStartBlock,
        uint72 indexed identityId,
        uint256 newScore
    );
    event NodeEpochScorePerStakeAdded(
        uint256 indexed epoch,
        uint72 indexed identityId,
        uint256 scorePerStakeToAdd,
        uint256 totalNodeEpochScorePerStake
    );
    event NodeEpochScorePerStakeSet(uint256 indexed epoch, uint72 indexed identityId, uint256 newScorePerStake);
    // D26 — C.2 EpochIndex events.
    event EpochCheckpointAppended(
        uint72 indexed identityId,
        uint256 indexed epoch,
        uint40 timestamp,
        uint256 scorePerStake36
    );
    event EpochNodeDelegatorScoreAdded(
        uint256 indexed epoch,
        uint72 indexed identityId,
        bytes32 indexed delegatorKey,
        uint256 scoreAdded,
        uint256 totalScore
    );
    event DelegatorLastSettledNodeEpochScorePerStakeSet(
        uint256 indexed epoch,
        uint72 indexed identityId,
        bytes32 indexed delegatorKey,
        uint256 newDelegatorLastSettledNodeEpochScorePerStake
    );
    event NodeChallengeSet(uint72 indexed identityId, RandomSamplingLib.Challenge challenge);
    /// @notice OT-RFC-49 / WS-E — a node's outstanding challenge was cleared by the
    ///         `clearOutstandingChallenges` migration sweep at the catalog-cutover redeploy.
    event NodeChallengeCleared(uint72 indexed identityId);
    event ActiveProofPeriodStartBlockSet(uint256 indexed activeProofPeriodStartBlock);
    event EpochNodeValidProofsCountIncremented(uint256 indexed epoch, uint72 indexed identityId, uint256 newCount);
    event EpochNodeValidProofsCountSet(uint256 indexed epoch, uint72 indexed identityId, uint256 newCount);
    event NodeEpochScoreSet(uint256 indexed epoch, uint72 indexed identityId, uint256 newScore);
    event AllNodesEpochScoreSet(uint256 indexed epoch, uint256 newScore);
    event EpochNodeDelegatorScoreSet(
        uint256 indexed epoch,
        uint72 indexed identityId,
        bytes32 indexed delegatorKey,
        uint256 newScore
    );

    /**
     * @dev Initializes the RandomSamplingStorage contract with initial parameters
     * Sets up proofing period duration, block time, and weight parameters for random sampling
     * @param hubAddress Address of the Hub contract for access control and contract dependencies
     * @param _proofingPeriodDurationInBlocks Initial duration of proofing periods in blocks
     * @param _w1 First weight parameter used in rewards calculations
     * @param _w2 Second weight parameter used in rewards calculations
     */
    constructor(
        address hubAddress,
        uint16 _proofingPeriodDurationInBlocks,
        uint256 _w1,
        uint256 _w2
    ) ContractStatus(hubAddress) {
        require(_proofingPeriodDurationInBlocks > 0, "Proofing period duration in blocks must be greater than 0");

        Chronos c = Chronos(hub.getContractAddress("Chronos"));

        proofingPeriodDurations.push(
            RandomSamplingLib.ProofingPeriodDuration({
                durationInBlocks: _proofingPeriodDurationInBlocks,
                effectiveEpoch: c.getCurrentEpoch()
            })
        );
        w1 = _w1;
        w2 = _w2;

        emit ProofingPeriodDurationAdded(_proofingPeriodDurationInBlocks, c.getCurrentEpoch());
        emit W1Set(0, _w1);
        emit W2Set(0, _w2);
    }

    // @dev Only transactions by HubController owner or one of the owners of the MultiSig Wallet
    modifier onlyOwnerOrMultiSigOwner() {
        _checkOwnerOrMultiSigOwner();
        _;
    }

    /**
     * @dev Initializes the contract by setting up the Chronos reference from the hub
     * Called once after deployment to complete contract setup
     */
    function initialize() external onlyHub {
        chronos = Chronos(hub.getContractAddress("Chronos"));
    }

    /**
     * @dev Returns the name of this contract for identification purposes
     * @return Contract name as a string
     */
    function name() external pure virtual override returns (string memory) {
        return _NAME;
    }

    /**
     * @dev Returns the version of this contract for compatibility tracking
     * @return Contract version as a string
     */
    function version() external pure virtual override returns (string memory) {
        return _VERSION;
    }

    /**
     * @dev Updates the w1 parameter used in rewards calculations
     * Can only be called by the hub owner or multisig owners
     * @param _w1 New w1 parameter value
     */
    function setW1(uint256 _w1) external onlyOwnerOrMultiSigOwner {
        uint256 oldW1 = w1;
        w1 = _w1;
        emit W1Set(oldW1, w1);
    }

    /**
     * @dev Returns the current w1 parameter value
     * @return Current w1 parameter used in rewards calculations
     */
    function getW1() external view returns (uint256) {
        return w1;
    }

    /**
     * @dev Updates the w2 parameter used in rewards calculations
     * Can only be called by the hub owner or multisig owners
     * @param _w2 New w2 parameter value
     */
    function setW2(uint256 _w2) external onlyOwnerOrMultiSigOwner {
        uint256 oldW2 = w2;
        w2 = _w2;
        emit W2Set(oldW2, w2);
    }

    /**
     * @dev Returns the current w2 parameter value
     * @return Current w2 parameter used in rewards calculations
     */
    function getW2() external view returns (uint256) {
        return w2;
    }

    /**
     * @dev Returns the current active proof period start block
     * @return Current active proof period start block number
     */
    function getActiveProofPeriodStartBlock() external view returns (uint256) {
        return activeProofPeriodStartBlock;
    }

    /**
     * @dev Sets the active proof period start block
     * Can only be called by contracts registered in the Hub
     * @param newActiveProofPeriodStartBlock New active proof period start block
     */
    function setActiveProofPeriodStartBlock(uint256 newActiveProofPeriodStartBlock) external onlyContracts {
        activeProofPeriodStartBlock = newActiveProofPeriodStartBlock;
        emit ActiveProofPeriodStartBlockSet(newActiveProofPeriodStartBlock);
    }

    /**
     * @dev Replaces a pending proofing period duration with new values before it becomes active
     * Can only be called by contracts registered in the Hub
     * @param durationInBlocks New duration in blocks for the proofing period
     * @param effectiveEpoch Epoch when the new duration will take effect
     */
    function replacePendingProofingPeriodDuration(
        uint16 durationInBlocks,
        uint256 effectiveEpoch
    ) external onlyContracts {
        uint16 oldDurationInBlocks = proofingPeriodDurations[proofingPeriodDurations.length - 1].durationInBlocks;
        proofingPeriodDurations[proofingPeriodDurations.length - 1] = RandomSamplingLib.ProofingPeriodDuration({
            durationInBlocks: durationInBlocks,
            effectiveEpoch: effectiveEpoch
        });

        emit PendingProofingPeriodDurationReplaced(oldDurationInBlocks, durationInBlocks, effectiveEpoch);
    }

    /**
     * @dev Adds a new proofing period duration to take effect at a future epoch
     * Can only be called by contracts registered in the Hub
     * @param durationInBlocks Duration in blocks for the new proofing period
     * @param effectiveEpoch Epoch when the new duration will take effect
     */
    function addProofingPeriodDuration(uint16 durationInBlocks, uint256 effectiveEpoch) external onlyContracts {
        proofingPeriodDurations.push(
            RandomSamplingLib.ProofingPeriodDuration({
                durationInBlocks: durationInBlocks,
                effectiveEpoch: effectiveEpoch
            })
        );

        emit ProofingPeriodDurationAdded(durationInBlocks, effectiveEpoch);
    }

    /**
     * @dev Returns the proofing period duration for a specific epoch
     * @param epoch The epoch to get the duration for
     * @return Duration in blocks for the specified epoch
     */
    function getEpochProofingPeriodDurationInBlocks(uint256 epoch) external view returns (uint16) {
        // Find the most recent duration that was effective before or at the specified epoch
        for (uint256 i = proofingPeriodDurations.length; i > 0; ) {
            if (epoch >= proofingPeriodDurations[i - 1].effectiveEpoch) {
                return proofingPeriodDurations[i - 1].durationInBlocks;
            }

            unchecked {
                i--;
            }
        }

        // If no applicable duration found, revert
        revert("No applicable duration found");
    }

    /**
     * @dev Returns the length of the proofing period durations array
     * @return Length of the proofing period durations array
     */
    function getProofingPeriodDurationsLength() external view returns (uint256) {
        return proofingPeriodDurations.length;
    }

    /**
     * @dev Returns the effective epoch of the latest proofing period duration
     * @return Effective epoch of the latest duration
     */
    function getLatestProofingPeriodDurationEffectiveEpoch() external view returns (uint256) {
        return proofingPeriodDurations[proofingPeriodDurations.length - 1].effectiveEpoch;
    }

    /**
     * @dev Returns the duration in blocks of the latest proofing period duration
     * @return Duration in blocks of the latest proofing period duration
     */
    function getLatestProofingPeriodDurationInBlocks() external view returns (uint16) {
        return proofingPeriodDurations[proofingPeriodDurations.length - 1].durationInBlocks;
    }

    /**
     * @dev Returns the proofing period duration struct for a specific index
     * @param index The index to get the duration for
     * @return Proofing period duration struct for the specified index
     */
    function getProofingPeriodDurationFromIndex(
        uint256 index
    ) external view returns (RandomSamplingLib.ProofingPeriodDuration memory) {
        return proofingPeriodDurations[index];
    }

    /**
     * @dev Returns the current challenge assigned to a specific node
     * Challenges are used to verify proofs during random sampling
     * @param identityId The node identity ID to get the challenge for
     * @return Challenge struct containing all challenge details
     */
    function getNodeChallenge(uint72 identityId) external view returns (RandomSamplingLib.Challenge memory) {
        return nodesChallenges[identityId];
    }

    /**
     * @dev Sets a new challenge for a specific node
     * Can only be called by contracts registered in the Hub
     * @param identityId The node identity ID to set the challenge for
     * @param challenge The challenge struct containing all challenge details
     */
    function setNodeChallenge(
        uint72 identityId,
        RandomSamplingLib.Challenge calldata challenge
    ) external onlyContracts {
        nodesChallenges[identityId] = challenge;
        emit NodeChallengeSet(identityId, challenge);
    }

    /// @notice G-3 — snapshot the node's effective stake at challenge creation so
    ///         submitProof can score against min(snapshot, live), defeating a
    ///         within-period flash-stake spike. `createChallenge` always sets this;
    ///         a 0 value (only reachable via the privileged setNodeChallenge path)
    ///         means "no snapshot" and submitProof applies no cap.
    function setNodeChallengeStakeSnapshot(uint72 identityId, uint256 stake18) external onlyContracts {
        nodeChallengeStakeSnapshot[identityId] = stake18;
        nodeChallengeStakeSnapshotSet[identityId] = true;
    }

    /// @notice OT-RFC-49 / WS-E migration — clear outstanding (unsolved) random-
    ///         sampling challenges across the redeploy that swaps the curated
    ///         proof surface from the private ciphertext to the public `_catalog`.
    ///
    /// A challenge issued in period N against the OLD (ciphertext) surface must
    /// not survive the cutover: post-upgrade the pinned `challengeRoot`/
    /// `challengeLeafCount` fields read as their zero default for any pre-upgrade
    /// challenge (they were appended to the struct in this version), so `submitProof`
    /// already reverts them via its `leafCount == 0` bounds check — but a node then
    /// sits with an unsolved challenge it can neither solve nor (mid-period) replace.
    /// This admin sweep deletes them so every node re-draws cleanly against the
    /// catalog surface on the next `createChallenge`. The operator supplies the set
    /// of node `identityId`s with outstanding challenges (enumerable off-chain from
    /// `ChallengeGenerated`/`NodeChallengeSet` logs) and runs this ONCE as part of
    /// the epoch-boundary cut. Idempotent: deleting an already-empty entry is a no-op.
    ///
    /// @param identityIds the node identity ids whose challenge slot to clear.
    function clearOutstandingChallenges(uint72[] calldata identityIds) external onlyOwnerOrMultiSigOwner {
        for (uint256 i = 0; i < identityIds.length; i++) {
            delete nodesChallenges[identityIds[i]];
            emit NodeChallengeCleared(identityIds[i]);
        }
    }

    /**
     * @dev Returns the score earned by a node during a specific epoch and proof period
     * @param identityId The node identity ID to get the score for
     * @param epoch The epoch to get the score for
     * @param proofPeriodStartBlock The start block of the proof period
     * @return Score earned by the node in the specified epoch and proof period, scaled by 10^18
     */
    function getNodeEpochProofPeriodScore(
        uint72 identityId,
        uint256 epoch,
        uint256 proofPeriodStartBlock
    ) external view returns (uint256) {
        return nodeEpochProofPeriodScore[identityId][epoch][proofPeriodStartBlock];
    }

    /**
     * @dev Increments the count of valid proofs submitted by a node in an epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to increment the count for
     * @param identityId The node identity ID to increment the count for
     */
    function incrementEpochNodeValidProofsCount(uint256 epoch, uint72 identityId) external onlyContracts {
        epochNodeValidProofsCount[epoch][identityId] += 1;
        emit EpochNodeValidProofsCountIncremented(epoch, identityId, epochNodeValidProofsCount[epoch][identityId]);
    }

    function setEpochNodeValidProofsCount(uint256 epoch, uint72 identityId, uint256 count) external onlyContracts {
        epochNodeValidProofsCount[epoch][identityId] = count;
        emit EpochNodeValidProofsCountSet(epoch, identityId, count);
    }

    /**
     * @dev Returns the number of valid proofs submitted by a node in a specific epoch
     * @param epoch The epoch to get the count for
     * @param identityId The node identity ID to get the count for
     * @return Number of valid proofs submitted by the node in the specified epoch
     */
    function getEpochNodeValidProofsCount(uint256 epoch, uint72 identityId) external view returns (uint256) {
        return epochNodeValidProofsCount[epoch][identityId];
    }

    /**
     * @dev Adds to the total score earned by a node in a specific epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to add the score to
     * @param identityId The node identity ID to add the score for
     * @param score The score amount to add, scaled by 10^18
     */
    function addToNodeEpochScore(uint256 epoch, uint72 identityId, uint256 score) external onlyContracts {
        nodeEpochScore[identityId][epoch] += score;
        emit NodeEpochScoreAdded(epoch, identityId, score, nodeEpochScore[identityId][epoch]);
    }

    /**
     * @dev Sets a node's score for a specific epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to set the score for
     * @param identityId The node identity ID to set the score for
     * @param score The score amount to set, scaled by 10^18
     */
    function setNodeEpochScore(uint256 epoch, uint72 identityId, uint256 score) external onlyContracts {
        nodeEpochScore[identityId][epoch] = score;
        emit NodeEpochScoreSet(epoch, identityId, score);
    }

    /**
     * @dev Returns the total score earned by a node in a specific epoch
     * @param epoch The epoch to get the score for
     * @param identityId The node identity ID to get the score for
     * @return Total score earned by the node in the specified epoch, scaled by 10^18
     */
    function getNodeEpochScore(uint256 epoch, uint72 identityId) external view returns (uint256) {
        return nodeEpochScore[identityId][epoch];
    }

    /**
     * @dev Adds to the total score of all nodes in a specific epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to add the score to
     * @param score The score amount to add to the total, scaled by 10^18
     */
    function addToAllNodesEpochScore(uint256 epoch, uint256 score) external onlyContracts {
        allNodesEpochScore[epoch] += score;
        emit AllNodesEpochScoreAdded(epoch, score, allNodesEpochScore[epoch]);
    }

    /**
     * @dev Sets the total score of all nodes in a specific epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to set the score for
     * @param score The score amount to set, scaled by 10^18
     */
    function setAllNodesEpochScore(uint256 epoch, uint256 score) external onlyContracts {
        allNodesEpochScore[epoch] = score;
        emit AllNodesEpochScoreSet(epoch, score);
    }

    /**
     * @dev Returns the total score of all nodes in a specific epoch
     * @param epoch The epoch to get the total score for
     * @return Total score of all nodes in the specified epoch, scaled by 10^18
     */
    function getAllNodesEpochScore(uint256 epoch) external view returns (uint256) {
        return allNodesEpochScore[epoch];
    }

    /**
     * @dev Adds to a node's score for a specific epoch and proof period
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to add the score to
     * @param proofPeriodStartBlock The start block of the proof period
     * @param identityId The node identity ID to add the score for
     * @param score The score amount to add, scaled by 10^18
     */
    function addToNodeEpochProofPeriodScore(
        uint256 epoch,
        uint256 proofPeriodStartBlock,
        uint72 identityId,
        uint256 score
    ) external onlyContracts {
        nodeEpochProofPeriodScore[identityId][epoch][proofPeriodStartBlock] += score;
        emit NodeEpochProofPeriodScoreAdded(
            epoch,
            proofPeriodStartBlock,
            identityId,
            score,
            nodeEpochProofPeriodScore[identityId][epoch][proofPeriodStartBlock]
        );
    }

    /**
     * @dev Sets a node's score for a specific epoch and proof period
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to set the score for
     * @param proofPeriodStartBlock The start block of the proof period
     * @param identityId The node identity ID to set the score for
     * @param score The score amount to set, scaled by 10^18
     */
    function setNodeEpochProofPeriodScore(
        uint256 epoch,
        uint256 proofPeriodStartBlock,
        uint72 identityId,
        uint256 score
    ) external onlyContracts {
        nodeEpochProofPeriodScore[identityId][epoch][proofPeriodStartBlock] = score;
        emit NodeEpochProofPeriodScoreSet(epoch, proofPeriodStartBlock, identityId, score);
    }

    /**
     * @dev Returns the score earned by a specific node's delegator in an epoch
     * Used for calculating delegator rewards
     * @param epoch The epoch to get the score for
     * @param identityId The node identity ID the delegator is delegating to
     * @param delegatorKey The unique key identifying the delegator
     * @return Score earned by the delegator for the specified node in the epoch, scaled by 10^18
     */
    function getEpochNodeDelegatorScore(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey
    ) external view returns (uint256) {
        return epochNodeDelegatorScore[epoch][identityId][delegatorKey];
    }

    /**
     * @dev Adds to the score earned by a node's delegator in an epoch
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to add the score to
     * @param identityId The node identity ID the delegator is delegating to
     * @param delegatorKey The unique key identifying the delegator
     * @param score The score amount to add, scaled by 10^18
     */
    function addToEpochNodeDelegatorScore(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey,
        uint256 score
    ) external onlyContracts {
        epochNodeDelegatorScore[epoch][identityId][delegatorKey] += score;
        emit EpochNodeDelegatorScoreAdded(
            epoch,
            identityId,
            delegatorKey,
            score,
            epochNodeDelegatorScore[epoch][identityId][delegatorKey]
        );
    }

    function setEpochNodeDelegatorScore(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey,
        uint256 score
    ) external onlyContracts {
        epochNodeDelegatorScore[epoch][identityId][delegatorKey] = score;
        emit EpochNodeDelegatorScoreSet(epoch, identityId, delegatorKey, score);
    }

    /**
     * @dev Adapter for the pre-D26 read signature. Returns
     *      `lastScorePerStake36` for `(identityId, epoch)` — semantically
     *      identical to the pre-D26 scalar for past (fully-settled) epochs,
     *      which is all V8 call sites ever read.
     */
    function getNodeEpochScorePerStake(uint256 epoch, uint72 identityId) external view returns (uint256) {
        return nodeEpochIndex[identityId][epoch].lastScorePerStake36;
    }

    /**
     * @dev Legacy adapter retained for test harnesses (and any V8 emergency
     *      path) that used to write the per-epoch score-per-stake scalar
     *      directly. Routes through the new EpochIndex: bumps
     *      `lastScorePerStake36` by `scorePerStakeToAdd`, and appends /
     *      updates a `Checkpoint` at `block.timestamp` so claim-time
     *      binary search sees the new value.
     */
    function addToNodeEpochScorePerStake(
        uint256 epoch,
        uint72 identityId,
        uint256 scorePerStakeToAdd
    ) external onlyContracts {
        EpochIndex storage ei = nodeEpochIndex[identityId][epoch];
        uint256 newLast = ei.lastScorePerStake36 + scorePerStakeToAdd;
        ei.lastScorePerStake36 = newLast;
        _upsertCheckpoint(ei, uint40(block.timestamp), newLast);
        emit NodeEpochScorePerStakeAdded(epoch, identityId, scorePerStakeToAdd, newLast);
    }

    /**
     * @dev Legacy adapter. Overwrites `lastScorePerStake36` to `scorePerStake`
     *      and appends/updates a Checkpoint at `block.timestamp`.
     */
    function setNodeEpochScorePerStake(uint256 epoch, uint72 identityId, uint256 scorePerStake) external onlyContracts {
        EpochIndex storage ei = nodeEpochIndex[identityId][epoch];
        ei.lastScorePerStake36 = scorePerStake;
        _upsertCheckpoint(ei, uint40(block.timestamp), scorePerStake);
        emit NodeEpochScorePerStakeSet(epoch, identityId, scorePerStake);
    }

    // ============================================================
    //          D26 — EpochIndex mutators (submitProof)
    // ============================================================

    /// @notice Append a timestamped checkpoint (or overwrite the last one if
    ///         its timestamp equals `ts`) and set
    ///         `lastScorePerStake36 = scorePerStake36`.
    ///
    ///         `scorePerStake36` is **epoch-local** (accumulates from 0 per
    ///         epoch).
    function appendCheckpoint(
        uint72 identityId,
        uint256 epoch,
        uint40 ts,
        uint256 scorePerStake36
    ) external onlyContracts {
        EpochIndex storage ei = nodeEpochIndex[identityId][epoch];
        require(scorePerStake36 <= type(uint216).max, "Checkpoint overflow");
        ei.lastScorePerStake36 = scorePerStake36;
        _upsertCheckpoint(ei, ts, scorePerStake36);
        emit EpochCheckpointAppended(identityId, epoch, ts, scorePerStake36);
    }

    // L6 — `setLastScorePerStake` removed. It could desynchronize the
    //      `mid[tail]` checkpoint from the `lastScorePerStake36` scalar
    //      (breaking the `findScorePerStakeAt` monotonicity contract).
    //      Tests that need to set state must go through `appendCheckpoint`
    //      or `addToNodeEpochScorePerStake`, which keep both sides
    //      consistent.

    function _upsertCheckpoint(EpochIndex storage ei, uint40 ts, uint256 value) internal {
        require(value <= type(uint216).max, "Checkpoint overflow");
        uint256 n = ei.mid.length;
        if (n > 0) {
            Checkpoint storage tail = ei.mid[n - 1];
            require(tail.timestamp <= ts, "Non-monotonic ts");
            if (tail.timestamp == ts) {
                tail.scorePerStake36 = uint216(value);
                return;
            }
        }
        ei.mid.push(Checkpoint({timestamp: ts, scorePerStake36: uint216(value)}));
    }

    // ============================================================
    //          D26 — EpochIndex views (claim-time)
    // ============================================================

    function getEpochLastScorePerStake(uint72 identityId, uint256 epoch) external view returns (uint256) {
        return nodeEpochIndex[identityId][epoch].lastScorePerStake36;
    }

    function getEpochCheckpointCount(uint72 identityId, uint256 epoch) external view returns (uint256) {
        return nodeEpochIndex[identityId][epoch].mid.length;
    }

    function getEpochCheckpoint(
        uint72 identityId,
        uint256 epoch,
        uint256 index
    ) external view returns (uint40 timestamp, uint256 scorePerStake36) {
        Checkpoint storage c = nodeEpochIndex[identityId][epoch].mid[index];
        return (c.timestamp, c.scorePerStake36);
    }

    /**
     * @notice Binary-search the per-(identityId, epoch) checkpoint array for
     *         the scorePerStake36 at timestamp `ts`. Returns the first
     *         sentinel if `ts` precedes every checkpoint (including when
     *         there are none). The returned value is monotonic in `ts`.
     */
    function findScorePerStakeAt(uint72 identityId, uint256 epoch, uint40 ts) external view returns (uint256) {
        EpochIndex storage ei = nodeEpochIndex[identityId][epoch];
        uint256 n = ei.mid.length;
        // M6 — no first-sentinel anymore; absent checkpoint → 0 (natural
        //      pre-any-proof default under D26's epoch-local accumulator).
        if (n == 0) {
            return 0;
        }
        // Largest i with mid[i].timestamp <= ts via binary search.
        uint256 lo = 0;
        uint256 hi = n;
        while (lo < hi) {
            uint256 mid = (lo + hi) >> 1;
            if (ei.mid[mid].timestamp <= ts) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo == 0) {
            return 0;
        }
        return ei.mid[lo - 1].scorePerStake36;
    }

    /**
     * @dev Returns the last settled score per stake value for a delegator
     * Used to track reward settlement state for delegators
     * @param epoch The epoch to get the last settled score per stake for
     * @param identityId The node identity ID the delegator is delegating to
     * @param delegatorKey The unique key identifying the delegator
     * @return Last settled score per stake value for the delegator, scaled by 10^36
     */
    function getDelegatorLastSettledNodeEpochScorePerStake(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey
    ) external view returns (uint256) {
        return delegatorLastSettledNodeEpochScorePerStake[epoch][identityId][delegatorKey];
    }

    /**
     * @dev Updates the last settled score per stake value for a delegator
     * Can only be called by contracts registered in the Hub
     * @param epoch The epoch to update the last settled score per stake for
     * @param identityId The node identity ID the delegator is delegating to
     * @param delegatorKey The unique key identifying the delegator
     * @param newNodeEpochScorePerStake The new score per stake value to set as last settled, scaled by 10^36
     */
    function setDelegatorLastSettledNodeEpochScorePerStake(
        uint256 epoch,
        uint72 identityId,
        bytes32 delegatorKey,
        uint256 newNodeEpochScorePerStake
    ) external onlyContracts {
        delegatorLastSettledNodeEpochScorePerStake[epoch][identityId][delegatorKey] = newNodeEpochScorePerStake;
        emit DelegatorLastSettledNodeEpochScorePerStakeSet(epoch, identityId, delegatorKey, newNodeEpochScorePerStake);
    }

    /**
     * @dev Internal function to check if an address is an owner of the multisig wallet
     * Used for access control in administrative functions
     * @param multiSigAddress Address of the multisig wallet to check ownership of
     * @return True if the caller is an owner of the multisig, false otherwise
     */
    function _isMultiSigOwner(address multiSigAddress) internal view returns (bool) {
        try ICustodian(multiSigAddress).getOwners() returns (address[] memory multiSigOwners) {
            for (uint256 i = 0; i < multiSigOwners.length; i++) {
                if (msg.sender == multiSigOwners[i]) {
                    return true;
                }
            }
        } catch {
            // Not a multisig or call reverted; treat as not owner.
        }

        return false;
    }

    /**
     * @dev Internal function to verify that the caller is either the hub owner or a multisig owner
     * Used by the onlyOwnerOrMultiSigOwner modifier for access control
     */
    function _checkOwnerOrMultiSigOwner() internal view virtual {
        address hubOwner = hub.owner();
        if (msg.sender != hubOwner && !_isMultiSigOwner(hubOwner)) {
            revert HubLib.UnauthorizedAccess("Only Hub Owner or Multisig Owner");
        }
    }
}
